/* NUTCADE Trust & help translations, generated from i18n_trust.py: added to the dictionaries in i18n.js */
(() => { const D = window.NUTCADE_I18N || {};
  const add = (d, t) => { for (const k in t) if (!(k in d.t)) d.t[k] = t[k]; };
  if (D.es) add(D.es, {"Updated to v{#}": "Actualizado a la v{#}", "What's new": "Novedades", "What's new in v{#}": "Novedades de la v{#}", "New version v{#} is ready. Reload when you're done.": "La nueva versión v{#} está lista. Recarga cuando termines.", "New version v{#} is ready.": "La nueva versión v{#} está lista.", "Reload now": "Recargar ahora", "Finish what you're doing first, then reload.": "Termina primero lo que estás haciendo y luego recarga.", "Time to check your 12 words. It takes a minute and nothing leaves this phone.": "Es hora de comprobar tus 12 palabras. Lleva un minuto y nada sale de este teléfono.", "Check now": "Comprobar ahora", "Send all": "Enviar todo", "Stays at this mint": "Se queda en este mint", "Leaves your balance": "Sale de tu saldo", "Network fee": "Comisión de red", "Create token for {#} SAT": "Crear token de {#} SAT", "Send all: everything at this mint, less the mint's fee.": "Enviar todo: todo lo que hay en este mint, menos la comisión del mint.", "Send all: everything at this mint, less the fees.": "Enviar todo: todo lo que hay en este mint, menos las comisiones.", "Your balance at this mint changed, so nothing was sent. Tap Send all again to see the new amount.": "Tu saldo en este mint cambió, así que no se envió nada. Toca Enviar todo otra vez para ver el nuevo importe.", "Nothing to send: this mint holds {#} SAT.": "Nada que enviar: este mint tiene {#} SAT.", "The fees ({#} SAT) are as much as this mint's balance of {#} SAT, so nothing can be sent from it.": "Las comisiones ({#} SAT) son tanto como el saldo de este mint, {#} SAT, así que no se puede enviar nada desde él.", "After the fees, {#} SAT would be left to send, less than the smallest payment allowed here ({#} SAT). Nothing was sent.": "Después de las comisiones quedarían {#} SAT para enviar, menos que el pago más pequeño permitido aquí ({#} SAT). No se envió nada.", "This mint takes at most {#} coins per request, and it holds {#} of yours, so Send all can't be used there. Type an amount instead.": "Este mint acepta como máximo {#} monedas por solicitud y tiene {#} tuyas, así que Enviar todo no se puede usar ahí. Escribe un importe.", "Send all isn't available with this mint right now. Type an amount instead.": "Enviar todo no está disponible con este mint ahora. Escribe un importe.", "This mint didn't say what the payment costs. Nothing was sent.": "Este mint no dijo cuánto cuesta el pago. No se envió nada.", "The fees kept changing, so Send all could not settle on an amount. Nothing was sent. Try again.": "Las comisiones seguían cambiando, así que Enviar todo no pudo fijar un importe. No se envió nada. Inténtalo de nuevo.", "The most this mint pays out at once is {#} SAT, so the rest stays at this mint.": "Lo máximo que este mint paga de una vez es {#} SAT, así que el resto se queda en este mint.", "The most this address or mint takes in one payment is {#} SAT, so the rest stays at this mint.": "Lo máximo que esta dirección o este mint acepta en un pago es {#} SAT, así que el resto se queda en este mint.", "Send all makes a token anyone can claim. Turn off the lock first, or type an amount.": "Enviar todo crea un token que cualquiera puede reclamar. Desactiva primero el bloqueo o escribe un importe.", "Send all needs the mint, and you're offline. Try again online.": "Enviar todo necesita el mint y no tienes conexión. Inténtalo de nuevo con conexión.", "Paste the Bitcoin address first.": "Pega primero la dirección Bitcoin.", "Send all: send everything at a mint in one go, as an ecash token, to a Lightning address or on-chain. NUTCADE works out the fees and shows exactly what will leave before anything is sent.": "Enviar todo: envía todo lo que hay en un mint de una vez, como token de ecash, a una dirección Lightning u on-chain. NUTCADE calcula las comisiones y muestra exactamente lo que saldrá antes de enviar nada.", "A receive note for an on-chain address nobody has paid yet is now hidden until a payment arrives. The price chart link now opens Settings at Show Bitcoin price.": "Una nota de recepción de una dirección on-chain que nadie ha pagado ahora se oculta hasta que llegue un pago. El enlace del gráfico de precios ahora abre Ajustes en Mostrar precio de Bitcoin.", "Send all uses only the mint you picked: your other mints are not touched. The spending limit and your PIN apply as for any payment.": "Enviar todo usa solo el mint que elegiste: tus otros mints no se tocan. El límite de gasto y tu PIN se aplican como en cualquier pago.", "NUTCADE can't save your wallet.": "NUTCADE no puede guardar tu cartera.", "This browser's storage is full, so your newest coins and changes exist only on this screen. Don't close or reload NUTCADE.": "El almacenamiento de este navegador está lleno, así que tus monedas y cambios más recientes solo existen en esta pantalla. No cierres ni recargues NUTCADE.", "Download a backup file now to keep a copy. Then free up space on this phone and tap Try again.": "Descarga ahora un archivo de respaldo para tener una copia. Luego libera espacio en este teléfono y toca Reintentar.", "If NUTCADE closes before it can save, use Find lost ecash in Settings, Backup: your 12 words bring those coins back.": "Si NUTCADE se cierra antes de poder guardar, usa Buscar ecash perdido en Ajustes, Respaldo: tus 12 palabras recuperan esas monedas.", "Storage for NUTCADE is {#}% full.": "El almacenamiento de NUTCADE está lleno al {#}%.", "Soon it may not be able to save your wallet. Download a backup file now, and free up space on this phone.": "Pronto podría no poder guardar tu cartera. Descarga ahora un archivo de respaldo y libera espacio en este teléfono.", "Download a backup file now and then to keep a copy.": "Descarga de vez en cuando un archivo de respaldo para tener una copia.", "Storage used by NUTCADE": "Almacenamiento usado por NUTCADE", "{#} MB / {#} MB ({#}%)": "{#} MB / {#} MB ({#}%)", "Add NUTCADE to your Home Screen, or Safari may delete this wallet.": "Añade NUTCADE a tu pantalla de inicio, o Safari podría borrar esta cartera.", "Show me how": "Muéstrame cómo", "Not today": "Hoy no", "Add to Home Screen": "Añadir a la pantalla de inicio", "Open NUTCADE in Safari.": "Abre NUTCADE en Safari.", "Tap Share (the square with an arrow; on newer iOS, tap ••• first).": "Toca Compartir (el cuadrado con una flecha; en iOS más reciente, toca ••• primero).", "Tap Add to Home Screen, then Add.": "Toca Añadir a pantalla de inicio y luego Añadir.", "From now on, open NUTCADE from the new icon.": "A partir de ahora, abre NUTCADE desde el nuevo icono.", "In Settings, Backup, tap Download backup and keep the file.": "En Ajustes, Respaldo, toca Descargar respaldo y guarda el archivo.", "The new icon keeps a wallet of its own and starts empty. Open it, tick the box, tap Create a new wallet and finish its setup steps (its words are replaced when you import), then tap Import backup in Settings, Backup and choose the file. Your wallet comes back as it was in the file. Then use only the icon.": "El nuevo icono tiene su propia cartera y empieza vacío. Ábrelo, marca la casilla, toca Crear una billetera nueva y termina sus pasos (sus palabras se reemplazan al importar), y luego toca Importar respaldo en Ajustes, Respaldo y elige el archivo. Tu cartera vuelve tal como estaba en el archivo. Después usa solo el icono.", "No backup file? Tap Restore from recovery phrase instead and enter your 12 words. That brings back the ecash made from your words at your mints, but not tokens still waiting to be claimed, locked ecash, ecash that didn't come from your words, or payments still in progress: settle those in Safari first.": "¿No tienes archivo de respaldo? Toca Restaurar con frase de recuperación y escribe tus 12 palabras. Eso recupera el ecash creado con tus palabras en tus mints, pero no los tokens que aún esperan ser reclamados, el ecash bloqueado, el ecash que no vino de tus palabras ni los pagos en curso: resuélvelos antes en Safari.", "Then set up your wallet from the new icon.": "Luego configura tu cartera desde el nuevo icono.", "Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "Safari puede borrar el almacenamiento de los sitios web que no has abierto en un tiempo, pero una app de la pantalla de inicio lo conserva.", "Steps for every device": "Pasos para cada dispositivo", "NUTCADE couldn't save your wallet: storage is full. Keep it open and read the notice on the wallet screen.": "NUTCADE no pudo guardar tu cartera: el almacenamiento está lleno. Mantenlo abierto y lee el aviso en la pantalla de la cartera.", "Can't lock now: your wallet isn't saved yet. Free up space first.": "No se puede bloquear ahora: tu cartera aún no está guardada. Libera espacio primero.", "Can't reload now: your wallet isn't saved yet. Free up space first.": "No se puede recargar ahora: tu cartera aún no está guardada. Libera espacio primero.", "Still can't save. Free up more space on this phone, then try again.": "Todavía no se puede guardar. Libera más espacio en este teléfono y vuelve a intentarlo.", "Saved. Your wallet is stored on this device again.": "Guardado. Tu cartera vuelve a estar guardada en este dispositivo.", "This browser won't save data, so NUTCADE stopped before using your recovery phrase. Free up space, then try again.": "Este navegador no guarda datos, así que NUTCADE se detuvo antes de usar tu frase de recuperación. Libera espacio y vuelve a intentarlo.", "This browser won't save data, so the PIN was not removed. Free up space and try again.": "Este navegador no guarda datos, así que el PIN no se quitó. Libera espacio y vuelve a intentarlo.", "This browser won't save data. Free up space and try again.": "Este navegador no guarda datos. Libera espacio y vuelve a intentarlo.", "If this browser can't save your wallet (storage full), NUTCADE now says so in red on the wallet screen, with what to do, instead of failing silently.": "Si este navegador no puede guardar tu cartera (almacenamiento lleno), NUTCADE ahora lo dice en rojo en la pantalla de la cartera, con qué hacer, en lugar de fallar en silencio.", "Settings, Backup shows how much storage NUTCADE uses, and the wallet screen warns when it is 70% and 90% full.": "Ajustes, Respaldo muestra cuánto almacenamiento usa NUTCADE, y la pantalla de la cartera avisa cuando está lleno al 70% y al 90%.", "On iPhone, the wallet screen reminds you to add NUTCADE to your Home Screen, so Safari does not delete your wallet.": "En iPhone, la pantalla de la cartera te recuerda añadir NUTCADE a tu pantalla de inicio, para que Safari no borre tu cartera.", "Choose how many recent notes the home screen shows, from 0 to 6, in Settings, Look & sound.": "Elige cuántas notas recientes muestra la pantalla de inicio, de 0 a 6, en Ajustes, Aspecto y sonido.", "The Hall of Fame shows each game's full name.": "El Salón de la Fama muestra el nombre completo de cada juego.", "New game: Nut Bowl, top-down arcade football. Pick a play, run it or throw it, and beat the clock.": "Juego nuevo: Nut Bowl, fútbol americano arcade visto desde arriba. Elige una jugada, corre o lanza, y gana al reloj.", "The arcade now has twelve cabinets, and Nut Bowl can be the Daily Challenge.": "La sala de juegos ya tiene doce máquinas, y Nut Bowl puede ser el Reto Diario.", "A very large balance no longer cuts off the SAT label on small screens.": "Un saldo muy grande ya no corta la etiqueta SAT en pantallas pequeñas.", "Claiming a saved ecash note now shows its amount once, and a second open tab can no longer start a second claim.": "Al reclamar un ecash guardado, el importe se muestra una sola vez, y una segunda pestaña abierta ya no puede iniciar un segundo reclamo.", "A deposit that was finished again after an interrupted answer now says \"+X received\" like any other arrival.": "Un depósito que se terminó de nuevo tras una respuesta interrumpida ahora dice «+X recibido» como cualquier otra llegada.", "Saved ecash claimed after you come back online no longer shows a toast next to its own arrival notice.": "El ecash guardado que se reclama al volver a estar en línea ya no muestra un aviso junto a su propia notificación de llegada.", "Recent notes on the home screen": "Notas recientes en la pantalla de inicio", "How many of your latest notes the home screen lists. All notes always shows the rest. Kept on this device.": "Cuántas de tus últimas notas muestra la pantalla de inicio. Todas las notas siempre muestra el resto. Se guarda en este dispositivo.", "Can't reach the mint right now. Try again in a moment.": "No se puede conectar con el mint ahora mismo. Inténtalo de nuevo en un momento.", "A token you saved while offline is now claimed once, even if you tap Claim now while NUTCADE claims it too.": "Un token que guardaste sin conexión ahora se reclama una sola vez, aunque toques Reclamar ahora mientras NUTCADE también lo reclama.", "The home screen shows your last 2 notes. All notes shows the rest.": "La pantalla de inicio muestra tus últimas 2 notas. Todas las notas muestra el resto.", "Hide amounts also hides amounts in arrival notices.": "Ocultar importes también oculta los importes en los avisos de llegada.", "Hide amounts": "Ocultar importes", "Show amounts": "Mostrar importes", "Tap to hide amounts": "Toca para ocultar los importes", "Tap to show amounts": "Toca para mostrar los importes", "Shows ••• instead of amounts on the wallet, notes and mints screens. You can also tap your balance. Payment screens always show the real amount.": "Muestra ••• en lugar de los importes en las pantallas de cartera, notas y mints. También puedes tocar tu saldo. Las pantallas de pago siempre muestran el importe real.", "12 words last checked": "Últimas 12 palabras comprobadas", "NEVER": "NUNCA", "Check my 12 words": "Comprobar mis 12 palabras", "Last backup file": "Último archivo de respaldo", "A backup file only holds what your wallet held on the day you made it.": "Un archivo de respaldo solo contiene lo que tenía tu cartera el día que lo hiciste.", "Check your 12 words": "Comprueba tus 12 palabras", "Type these words from your paper copy, not from memory.": "Escribe estas palabras desde tu copia en papel, no de memoria.", "This check happens on this phone only. Your words are not shown, saved or sent anywhere.": "Esta comprobación se hace solo en este teléfono. Tus palabras no se muestran, no se guardan ni se envían a ningún sitio.", "Word #{#}": "Palabra n.º {#}", "Check": "Comprobar", "Show the words again": "Mostrar las palabras otra vez", "Not now": "Ahora no", "Later": "Más tarde", "Don't remind me again": "No volver a recordármelo", "Word #{#} doesn't match. Check your paper, or show the words again.": "La palabra n.º {#} no coincide. Revisa tu papel o muestra las palabras otra vez.", "Your 12 words check out. NUTCADE will ask again in about six months.": "Tus 12 palabras son correctas. NUTCADE volverá a preguntar en unos seis meses.", "OK. You can still check your words any time in Settings, Backup.": "De acuerdo. Aún puedes comprobar tus palabras cuando quieras en Ajustes, Respaldo.", "Notices when money arrives: a deposit, a token, a payment to your address. NUTCADE tells you, and shows what came in while you were away.": "Avisos cuando llega dinero: un depósito, un token, un pago a tu dirección. NUTCADE te lo dice y muestra lo que llegó mientras no estabas.", "Change your initials any time, in the Arcade or in Settings.": "Cambia tus iniciales cuando quieras, en la Sala de juegos o en Ajustes.", "Help & FAQ in Settings: short answers, offline, in five languages.": "Ayuda y preguntas frecuentes en Ajustes: respuestas cortas, sin conexión y en cinco idiomas.", "A check of your 12 words a week after your backup, and again twice a year. It happens on your phone only.": "Una comprobación de tus 12 palabras una semana después de tu respaldo y luego dos veces al año. Se hace solo en tu teléfono.", "Settings, Backup shows when you last made a backup file.": "Ajustes, Respaldo muestra cuándo hiciste tu último archivo de respaldo.", "Each mint's contact, terms and description, under Details in Mints.": "El contacto, las condiciones y la descripción de cada mint, en Detalles dentro de Mints.", "Hide amounts: tap your balance to show ••• instead of amounts.": "Ocultar importes: toca tu saldo para mostrar ••• en lugar de los importes.", "A note after each update, and a message when a new version is ready to load.": "Una nota tras cada actualización y un aviso cuando hay una versión nueva lista para cargar.", "A Privacy section that lists every service NUTCADE contacts, and why.": "Una sección de Privacidad que enumera cada servicio que contacta NUTCADE y por qué.", "Every release has signed checksums, so you can check that the files are the real ones.": "Cada versión tiene sumas de verificación firmadas, para que puedas comprobar que los archivos son los auténticos.", "Release page on GitHub": "Página de la versión en GitHub", "Checksums": "Sumas de verificación", "Done": "Listo", "Check for a new version": "Buscar una versión nueva", "CHECKING": "COMPROBANDO", "You have the newest version.": "Tienes la versión más reciente.", "Couldn't check right now.": "No se pudo comprobar ahora.", "Twelve cabinets of free play once you're in.": "Doce máquinas de juego libre en cuanto entres.", "Help": "Ayuda", "Help & FAQ": "Ayuda y preguntas frecuentes", "Short answers: what ecash is, a new phone, a stuck payment and what NUTCADE contacts. It works offline.": "Respuestas cortas: qué es el ecash, un teléfono nuevo, un pago atascado y a quién contacta NUTCADE. Funciona sin conexión.", "Report a problem": "Informar de un problema", "Report a security problem privately": "Informar de un problema de seguridad en privado", "What is NUTCADE?": "¿Qué es NUTCADE?", "NUTCADE is a wallet for Bitcoin, held as Cashu ecash, with an arcade built in. It runs in your browser.": "NUTCADE es una cartera de Bitcoin, guardado como ecash de Cashu, con un salón de juegos integrado. Funciona en tu navegador.", "There is no account to make, and nobody at NUTCADE can see or touch your sats.": "No hay que crear ninguna cuenta y nadie en NUTCADE puede ver ni tocar tus sats.", "What are ecash and a mint?": "¿Qué son el ecash y un mint?", "Ecash is money in the form of coins that sit on your device. A mint is a service that makes those coins and holds the Bitcoin behind them. You choose which mints to use.": "El ecash es dinero en forma de monedas que están en tu dispositivo. Un mint es un servicio que crea esas monedas y guarda el Bitcoin que las respalda. Tú eliges qué mints usar.", "Anyone can run a mint, so only use mints you trust. A mint sees the coins you exchange with it.": "Cualquiera puede gestionar un mint, así que usa solo mints en los que confíes. Un mint ve las monedas que intercambias con él.", "What if a mint closes or stops working?": "¿Y si un mint cierra o deja de funcionar?", "Your sats are a promise from the mint. If it closes or stops working, the ecash you hold there may not be spendable any more, and NUTCADE cannot bring it back.": "Tus sats son una promesa del mint. Si cierra o deja de funcionar, puede que el ecash que tienes allí ya no se pueda gastar, y NUTCADE no puede recuperarlo.", "So keep only what you can afford to lose at any one mint, and spread your sats over more than one. The Mints tab shows how each mint is doing, and its report card gives it a grade.": "Por eso, ten en cada mint solo lo que puedas permitirte perder y reparte tus sats entre más de uno. La pestaña Mints muestra cómo va cada mint y su ficha le da una nota.", "While a mint works, you can move sats to another one: Settings, Wallet tools, Move sats between mints.": "Mientras un mint funcione, puedes mover sats a otro: Ajustes, Herramientas, Mover sats entre mints.", "What are my 12 words?": "¿Qué son mis 12 palabras?", "They are your recovery phrase, and the only way to get your sats back if this phone is lost or its browser data is cleared. NUTCADE does not keep a copy.": "Son tu frase de recuperación y la única forma de recuperar tus sats si se pierde este teléfono o se borran los datos de su navegador. NUTCADE no guarda ninguna copia.", "Write them on paper, in order, and keep them offline. Never type them into a website, take a screenshot or send them to anyone, including anyone who says they are NUTCADE support.": "Escríbelas en papel, en orden, y guárdalas sin conexión. Nunca las escribas en un sitio web, ni hagas una captura de pantalla, ni se las envíes a nadie, ni siquiera a quien diga ser soporte de NUTCADE.", "Also write down the mints you use. Restoring scans the mints you list.": "Anota también los mints que usas. Al restaurar se exploran los mints que indiques.", "To practise, tap Check my 12 words in Settings, Backup. The check happens on this phone only.": "Para practicar, toca Comprobar mis 12 palabras en Ajustes, Respaldo. La comprobación se hace solo en este teléfono.", "I have a new phone, or I lost mine": "Tengo un teléfono nuevo o perdí el mío", "Open NUTCADE on the new device, tick the box and tap Restore from recovery phrase. Type your 12 words and tick the mints you used (Find my mints on Nostr can find them for you). NUTCADE scans those mints and rebuilds your balance.": "Abre NUTCADE en el dispositivo nuevo, marca la casilla y toca Restaurar con frase de recuperación. Escribe tus 12 palabras y marca los mints que usaste (Buscar mis mints en Nostr puede encontrarlos por ti). NUTCADE explora esos mints y reconstruye tu saldo.", "Your notes and history are not in your 12 words. They come back only from a backup file (Settings, Backup, Import backup).": "Tus notas y tu historial no están en tus 12 palabras. Solo vuelven desde un archivo de respaldo (Ajustes, Respaldo, Importar respaldo).", "A backup file holds your phrase and all your coins, so anyone who has it can spend your sats. Keep it private.": "Un archivo de respaldo contiene tu frase y todas tus monedas, así que cualquiera que lo tenga puede gastar tus sats. Mantenlo privado.", "A payment looks stuck": "Un pago parece atascado", "Open Settings, Wallet tools and tap Check stuck payments. A Lightning payment that fails returns your sats. One that is still waiting is tracked until the mint settles it.": "Abre Ajustes, Herramientas y toca Revisar pagos atascados. Un pago Lightning que falla devuelve tus sats. Uno que aún espera se sigue hasta que el mint lo resuelve.", "If NUTCADE closes halfway through a step, it finishes or puts it right the next time you open it.": "Si NUTCADE se cierra a mitad de un paso, lo termina o lo corrige la próxima vez que lo abras.", "If your balance looks too low, tap Find lost ecash in Settings, Backup. NUTCADE asks your mints for coins that belong to your 12 words and were never saved.": "Si tu saldo parece demasiado bajo, toca Buscar ecash perdido en Ajustes, Respaldo. NUTCADE pide a tus mints las monedas que pertenecen a tus 12 palabras y nunca se guardaron.", "Why isn't ecash mine until it is claimed?": "¿Por qué el ecash no es mío hasta que se reclama?", "A token is like cash in an envelope: whoever claims it first gets it. It is yours only once your wallet has claimed it.": "Un token es como dinero en un sobre: quien lo reclama primero se lo queda. Es tuyo solo cuando tu cartera lo ha reclamado.", "When you send a token, it shows as pending until the other person claims it. While it is unclaimed you can take it back with Reclaim.": "Cuando envías un token, aparece como pendiente hasta que la otra persona lo reclama. Mientras no se reclame, puedes recuperarlo con Recuperar.", "Offline, ecash that people give you is saved and claimed when you are back online. Until then it is not yours yet.": "Sin conexión, el ecash que te dan se guarda y se reclama cuando vuelves a estar en línea. Hasta entonces aún no es tuyo.", "What do fees cost?": "¿Cuánto cuestan las comisiones?", "A mint may charge a small fee to spend coins, and Lightning payments have a network fee. NUTCADE shows the fee before you confirm.": "Un mint puede cobrar una pequeña comisión por gastar monedas, y los pagos Lightning tienen una comisión de red. NUTCADE muestra la comisión antes de que confirmes.", "What do the PIN and the duress PIN do?": "¿Qué hacen el PIN y el PIN de coacción?", "A PIN locks NUTCADE and keeps your phrase, ecash and notes encrypted on this device. It stops someone who picks up your phone. It cannot stop malware on a device that is already compromised. If you forget it, reset the wallet and restore with your 12 words.": "Un PIN bloquea NUTCADE y mantiene tu frase, tu ecash y tus notas cifrados en este dispositivo. Detiene a quien coja tu teléfono. No puede detener un malware en un dispositivo ya comprometido. Si lo olvidas, restablece la cartera y restaura con tus 12 palabras.", "The duress PIN is a second PIN that opens a small, separate wallet instead of yours, for when someone makes you unlock NUTCADE. It helps against a person standing in front of you. It does not help against someone who studies your phone with the app's open code.": "El PIN de coacción es un segundo PIN que abre una cartera pequeña y separada en lugar de la tuya, para cuando alguien te obligue a desbloquear NUTCADE. Ayuda frente a una persona que tienes delante. No ayuda frente a alguien que estudie tu teléfono con el código abierto de la app.", "Face ID or fingerprint opens your real wallet only, so turn it off if you rely on the duress PIN.": "Face ID o la huella abren solo tu cartera real, así que desactívalos si cuentas con el PIN de coacción.", "Can I use it offline?": "¿Puedo usarlo sin conexión?", "Open NUTCADE once while online and it keeps a copy, so it opens without a connection after that. Offline, you can send ecash for amounts made of the exact coins you hold.": "Abre NUTCADE una vez con conexión y guarda una copia, así que después se abre sin conexión. Sin conexión, puedes enviar ecash por importes formados con las monedas exactas que tienes.", "Hide my amounts": "Ocultar mis importes", "Tap your balance, or the eye button beside it, to show ••• instead of amounts on the wallet, notes and mints screens. It is remembered on this device.": "Toca tu saldo, o el botón del ojo a su lado, para mostrar ••• en lugar de los importes en las pantallas de cartera, notas y mints. Se recuerda en este dispositivo.", "Payment screens always show the real amount, so you know what you are about to send.": "Las pantallas de pago siempre muestran el importe real, para que sepas lo que vas a enviar.", "How do updates work?": "¿Cómo funcionan las actualizaciones?", "NUTCADE updates itself: the next time you open it, it loads the new version, and a note tells you what changed.": "NUTCADE se actualiza solo: la próxima vez que lo abras, carga la versión nueva y una nota te dice qué cambió.", "If you keep it open for days, a message says when a new version is ready. Reload when you are done: NUTCADE never reloads by itself, and never offers it in the middle of a payment.": "Si lo mantienes abierto durante días, un mensaje avisa cuando hay una versión nueva lista. Recarga cuando termines: NUTCADE nunca se recarga solo y nunca lo ofrece en medio de un pago.", "Keeping your wallet safe": "Cómo mantener segura tu cartera", "The only real address is https://random21m.github.io/nutcade/. Anything else that calls itself NUTCADE is not us.": "La única dirección real es https://random21m.github.io/nutcade/. Cualquier otra que se llame NUTCADE no somos nosotros.", "On iPhone, add NUTCADE to your Home Screen. Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "En iPhone, añade NUTCADE a tu pantalla de inicio. Safari puede borrar el almacenamiento de los sitios web que llevas tiempo sin abrir, pero una app de la pantalla de inicio lo conserva.", "Set a PIN, keep your 12 words offline, and start with small amounts: NUTCADE is young software that has not been independently audited.": "Pon un PIN, guarda tus 12 palabras sin conexión y empieza con importes pequeños: NUTCADE es un software joven que no ha sido auditado de forma independiente.", "What does NUTCADE contact? (Privacy)": "¿A quién contacta NUTCADE? (Privacidad)", "NUTCADE has no account, no tracking, no analytics and no ads. It contacts these services, and only for the reason given:": "NUTCADE no tiene cuenta, ni rastreo, ni analítica, ni anuncios. Contacta estos servicios, y solo por el motivo indicado:", "Your mints: for every payment, to check that they answer, and to read their name and contact details. A mint sees the coins you exchange with it.": "Tus mints: en cada pago, para comprobar que responden y para leer su nombre y sus datos de contacto. Un mint ve las monedas que intercambias con él.", "The mints in the Add mint list (Minibits, Cuba Bitcoin, 8333.space and two test mints), only while that list is open, to show whether they answer.": "Los mints de la lista Añadir mint (Minibits, Cuba Bitcoin, 8333.space y dos mints de prueba), solo mientras esa lista está abierta, para mostrar si responden.", "Nostr relays (relay.damus.io, nos.lol and relay.primal.net): for game challenges and payments between contacts, apps you connect with Wallet Connect, your encrypted mint list, requests you made and ecash sent to your ecash address. A contact or a payment request can name relays of its own, which are used when you send to them.": "Relés de Nostr (relay.damus.io, nos.lol y relay.primal.net): para desafíos de juegos y pagos entre contactos, las apps que conectas con Wallet Connect, tu lista de mints cifrada, las solicitudes que hiciste y el ecash enviado a tu dirección de ecash. Un contacto o una solicitud de pago pueden indicar relés propios, que se usan cuando les envías algo.", "Two more relays (relay.nostr.band and relay.cashumints.space) are asked only when you tap Find mints people recommend.": "Otros dos relés (relay.nostr.band y relay.cashumints.space) se consultan solo cuando tocas Buscar mints que la gente recomienda.", "Coinbase, for the price and the price chart, only while Show Bitcoin price is on.": "Coinbase, para el precio y el gráfico de precios, solo mientras Mostrar precio de Bitcoin está activado.", "npub.cash, while your Lightning address is on, and npubx.cash, when you tip from inside the app (the tip address is an npubx.cash address).": "npub.cash, mientras tu dirección Lightning está activada y npubx.cash, cuando das una propina desde la app (la dirección de propinas es una dirección de npubx.cash).", "The web address of any Lightning address, LNURL, voucher or payment request you pay or scan, and of a Nostr profile when you zap it. It sees that one request.": "La dirección web de cualquier dirección Lightning, LNURL, cupón o solicitud de pago que pagues o escanees, y la de un perfil de Nostr cuando le haces un zap. Ve esa única solicitud.", "This website, to load NUTCADE, its QR scanner and the update check. GitHub, which hosts it, sees these requests like any website visit.": "Este sitio web, para cargar NUTCADE, su escáner QR y la comprobación de actualizaciones. GitHub, que lo aloja, ve estas solicitudes como en cualquier visita a un sitio web.", "GitHub pages (the source, release notes and the problem report form), only when you tap a link to them.": "Páginas de GitHub (el código fuente, las notas de versión y el formulario de informe de problemas), solo cuando tocas un enlace a ellas.", "The camera is used only while a scanner is open and the microphone only while a Listen screen is open. Nothing is recorded or sent.": "La cámara se usa solo mientras hay un escáner abierto y el micrófono solo mientras hay una pantalla de Escuchar abierta. No se graba ni se envía nada.", "Reporting a problem": "Informar de un problema", "Reports on GitHub are public. Never paste your 12 words, your PIN, a backup file or a token into one.": "Los informes en GitHub son públicos. Nunca pegues en ellos tus 12 palabras, tu PIN, un archivo de respaldo ni un token.", "For a security problem, use the private report link below, so that only the maintainer sees it.": "Para un problema de seguridad, usa el enlace de informe privado de abajo, para que solo lo vea quien mantiene el proyecto.", "Your initials": "Tus iniciales", "Shown on your high scores and on the challenges you play. Scores you already sent to friends keep the initials they were sent with.": "Se muestran en tus récords y en los desafíos que juegas. Las puntuaciones que ya enviaste a amigos conservan las iniciales con las que se enviaron.", "New initials (3 letters or numbers)": "Iniciales nuevas (3 letras o números)", "Also rename my past scores on this phone": "Cambiar también mis puntuaciones pasadas en este teléfono", "Save initials": "Guardar iniciales", "Use exactly 3 letters or numbers.": "Usa exactamente 3 letras o números.", "Initials saved.": "Iniciales guardadas.", "Arcade": "Arcade", "Details": "Detalles", "Mint details": "Detalles del mint", "ASKING THE MINT": "PREGUNTANDO AL MINT", "The mint did not answer, so there is nothing to show yet.": "El mint no respondió, así que aún no hay nada que mostrar.", "About this mint": "Sobre este mint", "In more detail": "Con más detalle", "Message from the mint": "Mensaje del mint", "Contact": "Contacto", "The mint lists no contact.": "El mint no indica ningún contacto.", "Terms of service": "Condiciones del servicio", "The mint lists no terms.": "El mint no indica condiciones.", "Software": "Software", "This text was written by the mint, not by NUTCADE. Read it with care: a mint that says it is safe has not been checked by us.": "Este texto lo escribió el mint, no NUTCADE. Léelo con cuidado: un mint que dice ser seguro no ha sido comprobado por nosotros.", "Extra protection: the app now refuses to run any code that is not its own, even if a bad mint or website tried to slip some in.": "Protección extra: la app ahora se niega a ejecutar código que no sea suyo, aunque un mint o un sitio web malo intente colarlo.", "The backup file can be protected with a password, and it now also saves contacts, settings, trophies and arcade progress.": "El archivo de respaldo se puede proteger con una contraseña y ahora también guarda contactos, ajustes, trofeos y el progreso del arcade.", "New, optional: Back up with my phone locks your 12 words with a passkey and keeps the locked copy on Nostr relays.": "Nuevo y opcional: Respaldar con mi teléfono bloquea tus 12 palabras con una llave de acceso y guarda la copia bloqueada en relés de Nostr.", "It also holds your contacts, settings, trophies and arcade progress.": "También guarda tus contactos, ajustes, trofeos y el progreso del arcade.", "Protect with a password": "Proteger con una contraseña", "The file can only be opened with the password you choose.": "El archivo solo se puede abrir con la contraseña que elijas.", "Choose a password for the file. Anyone with the file and the password can spend your sats.": "Elige una contraseña para el archivo. Cualquiera con el archivo y la contraseña puede gastar tus sats.", "Password": "Contraseña", "Same password again": "La misma contraseña otra vez", "NUTCADE can't recover a forgotten password. Your 12 words still restore your sats.": "NUTCADE no puede recuperar una contraseña olvidada. Tus 12 palabras siguen restaurando tus sats.", "Download locked backup": "Descargar respaldo bloqueado", "Locked backup file downloaded. Keep the password safe.": "Archivo de respaldo bloqueado descargado. Guarda bien la contraseña.", "Use at least 8 characters for the password.": "Usa al menos 8 caracteres para la contraseña.", "The two passwords don't match.": "Las dos contraseñas no coinciden.", "Backup password": "Contraseña del respaldo", "This backup is locked with a password.": "Este respaldo está bloqueado con una contraseña.", "Type the backup's password.": "Escribe la contraseña del respaldo.", "Wrong password, or the file is damaged. Nothing was changed.": "Contraseña incorrecta, o el archivo está dañado. No se cambió nada.", "This locked backup was made by a newer NUTCADE or is damaged. Nothing was changed.": "Este respaldo bloqueado lo hizo un NUTCADE más nuevo o está dañado. No se cambió nada.", "Back up with my phone": "Respaldar con mi teléfono", "Restore with my phone": "Restaurar con mi teléfono", "Locks your 12 words with a passkey (Face ID or fingerprint) and keeps the locked copy on Nostr relays. A new phone gets them back with the same passkey. Your 12 words stay your main backup.": "Bloquea tus 12 palabras con una llave de acceso (Face ID o huella) y guarda la copia bloqueada en relés de Nostr. Un teléfono nuevo las recupera con la misma llave de acceso. Tus 12 palabras siguen siendo tu respaldo principal.", "Phone backup": "Respaldo en el teléfono", "NOT SET UP": "SIN CONFIGURAR", "OUT OF DATE": "DESACTUALIZADO", "It holds your old 12 words. Tap Back up again to save the new ones.": "Guarda tus 12 palabras antiguas. Toca Respaldar de nuevo para guardar las nuevas.", "Back up again": "Respaldar de nuevo", "Remove phone backup": "Quitar respaldo en el teléfono", "Your Apple or Google account becomes a key to your wallet: anyone who gets into it can use the passkey to get your 12 words back. Keep that account safe, with two-step sign-in.": "Tu cuenta de Apple o Google se convierte en una llave de tu billetera: quien entre en ella puede usar la llave de acceso para recuperar tus 12 palabras. Protege esa cuenta con verificación en dos pasos.", "NUTCADE makes a passkey on this phone (kept in iCloud Keychain or Google Password Manager), locks your 12 words with it and saves the locked copy on Nostr relays. No server of ours is involved.": "NUTCADE crea una llave de acceso en este teléfono (guardada en el Llavero de iCloud o en el Gestor de contraseñas de Google), bloquea con ella tus 12 palabras y guarda la copia bloqueada en relés de Nostr. No interviene ningún servidor nuestro.", "Keep your 12 words on paper too. They are still your main backup.": "Guarda también tus 12 palabras en papel. Siguen siendo tu respaldo principal.", "BACKED UP!": "¡RESPALDADO!", "Your 12 words are locked with your passkey and saved on {#} relay. On a new phone, tap Restore with my phone.": "Tus 12 palabras están bloqueadas con tu llave de acceso y guardadas en {#} relé. En un teléfono nuevo, toca Restaurar con mi teléfono.", "Your 12 words are locked with your passkey and saved on {#} relays. On a new phone, tap Restore with my phone.": "Tus 12 palabras están bloqueadas con tu llave de acceso y guardadas en {#} relés. En un teléfono nuevo, toca Restaurar con mi teléfono.", "NUTCADE asks the Nostr relays to delete the locked copy of your 12 words. A relay that is down or ignores the request can keep it, still locked with your passkey.": "NUTCADE pide a los relés de Nostr que borren la copia bloqueada de tus 12 palabras. Un relé caído o que ignore la petición puede conservarla, todavía bloqueada con tu llave de acceso.", "You can also delete the passkey in your password manager.": "También puedes borrar la llave de acceso en tu gestor de contraseñas.", "REMOVING": "QUITANDO", "RESETTING": "RESTABLECIENDO", "Phone backup removed.": "Respaldo en el teléfono quitado.", "Your 12 words came from your phone backup. They are not shown here.": "Tus 12 palabras vienen de tu respaldo en el teléfono. No se muestran aquí.", "Enter your PIN to back up your 12 words with your phone.": "Introduce tu PIN para respaldar tus 12 palabras con tu teléfono.", "Back up with my phone isn't available right now. Try again later.": "Respaldar con mi teléfono no está disponible ahora. Inténtalo más tarde.", "Restore with my phone isn't available right now. Try again later.": "Restaurar con mi teléfono no está disponible ahora. Inténtalo más tarde.", "This phone or browser can't lock your words with a passkey. Nothing was saved. Your 12 words are still your backup.": "Este teléfono o navegador no puede bloquear tus palabras con una llave de acceso. No se guardó nada. Tus 12 palabras siguen siendo tu respaldo.", "Create or restore a wallet first.": "Primero crea o restaura una billetera.", "Back up with my phone needs a connection. Try again online.": "Respaldar con mi teléfono necesita conexión. Inténtalo de nuevo con conexión.", "Restore with my phone needs a connection. Try again online.": "Restaurar con mi teléfono necesita conexión. Inténtalo de nuevo con conexión.", "No Nostr relay answered, so nothing was saved. Check your connection and try again.": "Ningún relé de Nostr respondió, así que no se guardó nada. Revisa tu conexión e inténtalo de nuevo.", "No Nostr relay answered, so the phone backup is still there. Try again online.": "Ningún relé de Nostr respondió, así que el respaldo en el teléfono sigue ahí. Inténtalo de nuevo con conexión.", "The passkey step was cancelled. Nothing was changed.": "Se canceló el paso de la llave de acceso. No se cambió nada.", "That passkey isn't a NUTCADE phone backup. Nothing was changed.": "Esa llave de acceso no es un respaldo de NUTCADE en el teléfono. No se cambió nada.", "This phone or browser can't open a phone backup. Nothing was changed. Use your 12 words.": "Este teléfono o navegador no puede abrir un respaldo en el teléfono. No se cambió nada. Usa tus 12 palabras.", "No Nostr relay answered. Check your connection and try again. Nothing was changed.": "Ningún relé de Nostr respondió. Revisa tu conexión e inténtalo de nuevo. No se cambió nada.", "No phone backup was found for this passkey. Nothing was changed.": "No se encontró ningún respaldo en el teléfono para esta llave de acceso. No se cambió nada.", "This phone backup couldn't be opened with this passkey. Nothing was changed.": "Este respaldo en el teléfono no se pudo abrir con esta llave de acceso. No se cambió nada.", "This also deletes your phone backup from the Nostr relays, so Restore with my phone will not bring this wallet back. Without your 12 words, your sats are gone for good.": "Esto también borra tu respaldo en el teléfono de los relés de Nostr, así que Restaurar con mi teléfono no recuperará esta billetera. Sin tus 12 palabras, tus sats se pierden para siempre.", "Your phone backup holds this wallet's 12 words. If this changes them, the phone backup is out of date until you tap Back up again in Settings.": "Tu respaldo en el teléfono guarda las 12 palabras de esta billetera. Si esto las cambia, el respaldo en el teléfono queda desactualizado hasta que toques Respaldar de nuevo en Ajustes.", "After this, Restore with my phone will not bring this wallet back. Keep your 12 words.": "Después de esto, Restaurar con mi teléfono no recuperará esta billetera. Guarda tus 12 palabras.", "A phone backup, if you made one, is not deleted by this reset: it stays on the Nostr relays, and Restore with my phone can bring the wallet back.": "Un respaldo en el teléfono, si hiciste uno, no se borra con este restablecimiento: se queda en los relés de Nostr, y Restaurar con mi teléfono puede recuperar la billetera.", "The copy on the Nostr relays for this passkey holds other 12 words, saved from another phone or another wallet. Replacing it means that phone backup is lost.": "La copia en los relés de Nostr para esta llave de acceso guarda otras 12 palabras, guardadas desde otro teléfono u otra billetera. Reemplazarla significa perder ese respaldo en el teléfono.", "Replace anyway": "Reemplazar de todos modos", "Your phone backup's passkey wasn't found, or the step was cancelled. If you deleted the passkey, tap Remove phone backup, then back up again.": "No se encontró la llave de acceso de tu respaldo en el teléfono, o se canceló el paso. Si borraste la llave de acceso, toca Quitar respaldo en el teléfono y luego respalda de nuevo.", "Contacts: {#} added, {#} skipped (the same name or address is already here, or it wasn't valid).": "Contactos: {#} añadidos, {#} omitidos (ya hay uno con el mismo nombre o dirección, o no era válido)."});
  if (D.pt) add(D.pt, {"Updated to v{#}": "Atualizado para a v{#}", "What's new": "Novidades", "What's new in v{#}": "Novidades da v{#}", "New version v{#} is ready. Reload when you're done.": "A nova versão v{#} está pronta. Recarregue quando terminar.", "New version v{#} is ready.": "A nova versão v{#} está pronta.", "Reload now": "Recarregar agora", "Finish what you're doing first, then reload.": "Termine primeiro o que está fazendo e depois recarregue.", "Time to check your 12 words. It takes a minute and nothing leaves this phone.": "Hora de conferir suas 12 palavras. Leva um minuto e nada sai deste celular.", "Check now": "Verificar agora", "Send all": "Enviar tudo", "Stays at this mint": "Fica neste mint", "Leaves your balance": "Sai do seu saldo", "Network fee": "Taxa de rede", "Create token for {#} SAT": "Criar token de {#} SAT", "Send all: everything at this mint, less the mint's fee.": "Enviar tudo: tudo o que está neste mint, menos a taxa do mint.", "Send all: everything at this mint, less the fees.": "Enviar tudo: tudo o que está neste mint, menos as taxas.", "Your balance at this mint changed, so nothing was sent. Tap Send all again to see the new amount.": "Seu saldo neste mint mudou, então nada foi enviado. Toque em Enviar tudo de novo para ver o novo valor.", "Nothing to send: this mint holds {#} SAT.": "Nada para enviar: este mint tem {#} SAT.", "The fees ({#} SAT) are as much as this mint's balance of {#} SAT, so nothing can be sent from it.": "As taxas ({#} SAT) são tanto quanto o saldo deste mint, {#} SAT, então nada pode ser enviado dele.", "After the fees, {#} SAT would be left to send, less than the smallest payment allowed here ({#} SAT). Nothing was sent.": "Depois das taxas sobrariam {#} SAT para enviar, menos que o menor pagamento permitido aqui ({#} SAT). Nada foi enviado.", "This mint takes at most {#} coins per request, and it holds {#} of yours, so Send all can't be used there. Type an amount instead.": "Este mint aceita no máximo {#} moedas por pedido e tem {#} suas, então Enviar tudo não pode ser usado ali. Digite um valor.", "Send all isn't available with this mint right now. Type an amount instead.": "Enviar tudo não está disponível com este mint agora. Digite um valor.", "This mint didn't say what the payment costs. Nothing was sent.": "Este mint não disse quanto custa o pagamento. Nada foi enviado.", "The fees kept changing, so Send all could not settle on an amount. Nothing was sent. Try again.": "As taxas continuaram mudando, então Enviar tudo não conseguiu definir um valor. Nada foi enviado. Tente de novo.", "The most this mint pays out at once is {#} SAT, so the rest stays at this mint.": "O máximo que este mint paga de uma vez é {#} SAT, então o resto fica neste mint.", "The most this address or mint takes in one payment is {#} SAT, so the rest stays at this mint.": "O máximo que este endereço ou este mint aceita em um pagamento é {#} SAT, então o resto fica neste mint.", "Send all makes a token anyone can claim. Turn off the lock first, or type an amount.": "Enviar tudo cria um token que qualquer pessoa pode resgatar. Desative primeiro o bloqueio ou digite um valor.", "Send all needs the mint, and you're offline. Try again online.": "Enviar tudo precisa do mint e você está offline. Tente de novo quando estiver online.", "Paste the Bitcoin address first.": "Cole primeiro o endereço Bitcoin.", "Send all: send everything at a mint in one go, as an ecash token, to a Lightning address or on-chain. NUTCADE works out the fees and shows exactly what will leave before anything is sent.": "Enviar tudo: envie tudo o que está em um mint de uma vez, como token de ecash, para um endereço Lightning ou on-chain. O NUTCADE calcula as taxas e mostra exatamente o que vai sair antes de enviar qualquer coisa.", "A receive note for an on-chain address nobody has paid yet is now hidden until a payment arrives. The price chart link now opens Settings at Show Bitcoin price.": "Uma nota de recebimento de um endereço on-chain que ninguém pagou agora fica oculta até chegar um pagamento. O link do gráfico de preços agora abre os Ajustes em Mostrar preço do Bitcoin.", "Send all uses only the mint you picked: your other mints are not touched. The spending limit and your PIN apply as for any payment.": "Enviar tudo usa só o mint que você escolheu: seus outros mints não são tocados. O limite de gastos e o seu PIN valem como em qualquer pagamento.", "NUTCADE can't save your wallet.": "O NUTCADE não consegue salvar sua carteira.", "This browser's storage is full, so your newest coins and changes exist only on this screen. Don't close or reload NUTCADE.": "O armazenamento deste navegador está cheio, então suas moedas e mudanças mais recentes só existem nesta tela. Não feche nem recarregue o NUTCADE.", "Download a backup file now to keep a copy. Then free up space on this phone and tap Try again.": "Baixe agora um arquivo de backup para ter uma cópia. Depois libere espaço neste celular e toque em Tentar de novo.", "If NUTCADE closes before it can save, use Find lost ecash in Settings, Backup: your 12 words bring those coins back.": "Se o NUTCADE fechar antes de conseguir salvar, use Procurar ecash perdido em Ajustes, Backup: suas 12 palavras trazem essas moedas de volta.", "Storage for NUTCADE is {#}% full.": "O armazenamento do NUTCADE está {#}% cheio.", "Soon it may not be able to save your wallet. Download a backup file now, and free up space on this phone.": "Em breve ele pode não conseguir salvar sua carteira. Baixe agora um arquivo de backup e libere espaço neste celular.", "Download a backup file now and then to keep a copy.": "Baixe um arquivo de backup de vez em quando para ter uma cópia.", "Storage used by NUTCADE": "Armazenamento usado pelo NUTCADE", "{#} MB / {#} MB ({#}%)": "{#} MB / {#} MB ({#}%)", "Add NUTCADE to your Home Screen, or Safari may delete this wallet.": "Adicione o NUTCADE à sua Tela de Início, ou o Safari pode apagar esta carteira.", "Show me how": "Mostre como", "Not today": "Hoje não", "Add to Home Screen": "Adicionar à Tela de Início", "Open NUTCADE in Safari.": "Abra o NUTCADE no Safari.", "Tap Share (the square with an arrow; on newer iOS, tap ••• first).": "Toque em Compartilhar (o quadrado com uma seta; no iOS mais recente, toque em ••• primeiro).", "Tap Add to Home Screen, then Add.": "Toque em Adicionar à Tela de Início e depois em Adicionar.", "From now on, open NUTCADE from the new icon.": "A partir de agora, abra o NUTCADE pelo novo ícone.", "In Settings, Backup, tap Download backup and keep the file.": "Em Ajustes, Backup, toque em Baixar backup e guarde o arquivo.", "The new icon keeps a wallet of its own and starts empty. Open it, tick the box, tap Create a new wallet and finish its setup steps (its words are replaced when you import), then tap Import backup in Settings, Backup and choose the file. Your wallet comes back as it was in the file. Then use only the icon.": "O novo ícone tem a própria carteira e começa vazio. Abra-o, marque a caixa, toque em Criar uma carteira nova e conclua os passos dela (as palavras dela são trocadas ao importar) e depois toque em Importar backup em Ajustes, Backup e escolha o arquivo. Sua carteira volta como estava no arquivo. Depois use só o ícone.", "No backup file? Tap Restore from recovery phrase instead and enter your 12 words. That brings back the ecash made from your words at your mints, but not tokens still waiting to be claimed, locked ecash, ecash that didn't come from your words, or payments still in progress: settle those in Safari first.": "Não tem arquivo de backup? Toque em Restaurar com frase de recuperação e digite suas 12 palavras. Isso recupera o ecash criado com suas palavras nos seus mints, mas não tokens que ainda esperam ser resgatados, ecash bloqueado, ecash que não veio das suas palavras nem pagamentos em andamento: resolva isso antes no Safari.", "Then set up your wallet from the new icon.": "Depois configure sua carteira pelo novo ícone.", "Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "O Safari pode apagar o armazenamento de sites que você não abre há algum tempo, mas um app da Tela de Início o mantém.", "Steps for every device": "Passos para cada dispositivo", "NUTCADE couldn't save your wallet: storage is full. Keep it open and read the notice on the wallet screen.": "O NUTCADE não conseguiu salvar sua carteira: o armazenamento está cheio. Mantenha-o aberto e leia o aviso na tela da carteira.", "Can't lock now: your wallet isn't saved yet. Free up space first.": "Não é possível bloquear agora: sua carteira ainda não foi salva. Libere espaço primeiro.", "Can't reload now: your wallet isn't saved yet. Free up space first.": "Não é possível recarregar agora: sua carteira ainda não foi salva. Libere espaço primeiro.", "Still can't save. Free up more space on this phone, then try again.": "Ainda não é possível salvar. Libere mais espaço neste celular e tente de novo.", "Saved. Your wallet is stored on this device again.": "Salvo. Sua carteira está guardada neste dispositivo de novo.", "This browser won't save data, so NUTCADE stopped before using your recovery phrase. Free up space, then try again.": "Este navegador não salva dados, então o NUTCADE parou antes de usar sua frase de recuperação. Libere espaço e tente de novo.", "This browser won't save data, so the PIN was not removed. Free up space and try again.": "Este navegador não salva dados, então o PIN não foi removido. Libere espaço e tente de novo.", "This browser won't save data. Free up space and try again.": "Este navegador não salva dados. Libere espaço e tente de novo.", "If this browser can't save your wallet (storage full), NUTCADE now says so in red on the wallet screen, with what to do, instead of failing silently.": "Se este navegador não conseguir salvar sua carteira (armazenamento cheio), o NUTCADE agora avisa em vermelho na tela da carteira, com o que fazer, em vez de falhar em silêncio.", "Settings, Backup shows how much storage NUTCADE uses, and the wallet screen warns when it is 70% and 90% full.": "Ajustes, Backup mostra quanto armazenamento o NUTCADE usa, e a tela da carteira avisa quando está 70% e 90% cheio.", "On iPhone, the wallet screen reminds you to add NUTCADE to your Home Screen, so Safari does not delete your wallet.": "No iPhone, a tela da carteira lembra você de adicionar o NUTCADE à Tela de Início, para que o Safari não apague sua carteira.", "Choose how many recent notes the home screen shows, from 0 to 6, in Settings, Look & sound.": "Escolha quantas notas recentes a tela inicial mostra, de 0 a 6, em Ajustes, Aparência e som.", "The Hall of Fame shows each game's full name.": "O Hall da Fama mostra o nome completo de cada jogo.", "New game: Nut Bowl, top-down arcade football. Pick a play, run it or throw it, and beat the clock.": "Jogo novo: Nut Bowl, futebol americano arcade visto de cima. Escolha uma jogada, corra ou lance, e vença o relógio.", "The arcade now has twelve cabinets, and Nut Bowl can be the Daily Challenge.": "O fliperama agora tem doze máquinas, e o Nut Bowl pode ser o Desafio Diário.", "A very large balance no longer cuts off the SAT label on small screens.": "Um saldo muito grande não corta mais o rótulo SAT em telas pequenas.", "Claiming a saved ecash note now shows its amount once, and a second open tab can no longer start a second claim.": "Ao resgatar um ecash guardado, o valor aparece uma só vez, e uma segunda aba aberta não pode mais iniciar um segundo resgate.", "A deposit that was finished again after an interrupted answer now says \"+X received\" like any other arrival.": "Um depósito concluído de novo após uma resposta interrompida agora diz «+X recebido» como qualquer outra chegada.", "Saved ecash claimed after you come back online no longer shows a toast next to its own arrival notice.": "O ecash guardado resgatado ao voltar a ficar online não mostra mais um aviso ao lado da sua própria notificação de chegada.", "Recent notes on the home screen": "Notas recentes na tela inicial", "How many of your latest notes the home screen lists. All notes always shows the rest. Kept on this device.": "Quantas das suas últimas notas a tela inicial mostra. Todas as notas sempre mostra o resto. Fica salvo neste dispositivo.", "Can't reach the mint right now. Try again in a moment.": "Não foi possível conectar ao mint agora. Tente de novo daqui a pouco.", "A token you saved while offline is now claimed once, even if you tap Claim now while NUTCADE claims it too.": "Um token que você salvou off-line agora é resgatado uma só vez, mesmo que você toque em Resgatar agora enquanto o NUTCADE também o resgata.", "The home screen shows your last 2 notes. All notes shows the rest.": "A tela inicial mostra suas últimas 2 notas. Todas as notas mostra o resto.", "Hide amounts also hides amounts in arrival notices.": "Ocultar valores também oculta os valores nos avisos de chegada.", "Hide amounts": "Ocultar valores", "Show amounts": "Mostrar valores", "Tap to hide amounts": "Toque para ocultar os valores", "Tap to show amounts": "Toque para mostrar os valores", "Shows ••• instead of amounts on the wallet, notes and mints screens. You can also tap your balance. Payment screens always show the real amount.": "Mostra ••• no lugar dos valores nas telas de carteira, notas e mints. Você também pode tocar no seu saldo. As telas de pagamento sempre mostram o valor real.", "12 words last checked": "Últimas 12 palavras conferidas", "NEVER": "NUNCA", "Check my 12 words": "Conferir minhas 12 palavras", "Last backup file": "Último arquivo de backup", "A backup file only holds what your wallet held on the day you made it.": "Um arquivo de backup só guarda o que sua carteira tinha no dia em que você o fez.", "Check your 12 words": "Confira suas 12 palavras", "Type these words from your paper copy, not from memory.": "Digite estas palavras a partir da sua cópia em papel, não de memória.", "This check happens on this phone only. Your words are not shown, saved or sent anywhere.": "Esta conferência acontece só neste celular. Suas palavras não são mostradas, salvas nem enviadas a lugar nenhum.", "Word #{#}": "Palavra nº {#}", "Check": "Conferir", "Show the words again": "Mostrar as palavras de novo", "Not now": "Agora não", "Later": "Depois", "Don't remind me again": "Não me lembrar de novo", "Word #{#} doesn't match. Check your paper, or show the words again.": "A palavra nº {#} não confere. Veja seu papel ou mostre as palavras de novo.", "Your 12 words check out. NUTCADE will ask again in about six months.": "Suas 12 palavras estão certas. O NUTCADE vai perguntar de novo em cerca de seis meses.", "OK. You can still check your words any time in Settings, Backup.": "Certo. Você ainda pode conferir suas palavras quando quiser em Ajustes, Backup.", "Notices when money arrives: a deposit, a token, a payment to your address. NUTCADE tells you, and shows what came in while you were away.": "Avisos quando chega dinheiro: um depósito, um token, um pagamento ao seu endereço. O NUTCADE avisa e mostra o que chegou enquanto você estava fora.", "Change your initials any time, in the Arcade or in Settings.": "Mude suas iniciais quando quiser, no Fliperama ou em Ajustes.", "Help & FAQ in Settings: short answers, offline, in five languages.": "Ajuda e perguntas frequentes em Ajustes: respostas curtas, offline e em cinco idiomas.", "A check of your 12 words a week after your backup, and again twice a year. It happens on your phone only.": "Uma conferência das suas 12 palavras uma semana depois do seu backup e depois duas vezes por ano. Acontece só no seu celular.", "Settings, Backup shows when you last made a backup file.": "Ajustes, Backup mostra quando você fez seu último arquivo de backup.", "Each mint's contact, terms and description, under Details in Mints.": "O contato, os termos e a descrição de cada mint, em Detalhes dentro de Mints.", "Hide amounts: tap your balance to show ••• instead of amounts.": "Ocultar valores: toque no seu saldo para mostrar ••• no lugar dos valores.", "A note after each update, and a message when a new version is ready to load.": "Um aviso depois de cada atualização e uma mensagem quando uma nova versão estiver pronta para carregar.", "A Privacy section that lists every service NUTCADE contacts, and why.": "Uma seção de Privacidade que lista cada serviço que o NUTCADE contata e por quê.", "Every release has signed checksums, so you can check that the files are the real ones.": "Cada versão tem checksums assinados, para você conferir que os arquivos são os verdadeiros.", "Release page on GitHub": "Página da versão no GitHub", "Checksums": "Checksums", "Done": "Pronto", "Check for a new version": "Procurar uma nova versão", "CHECKING": "VERIFICANDO", "You have the newest version.": "Você tem a versão mais recente.", "Couldn't check right now.": "Não foi possível verificar agora.", "Twelve cabinets of free play once you're in.": "Doze máquinas de jogo grátis assim que você entrar.", "Help": "Ajuda", "Help & FAQ": "Ajuda e perguntas frequentes", "Short answers: what ecash is, a new phone, a stuck payment and what NUTCADE contacts. It works offline.": "Respostas curtas: o que é ecash, um celular novo, um pagamento travado e quem o NUTCADE contata. Funciona offline.", "Report a problem": "Relatar um problema", "Report a security problem privately": "Relatar um problema de segurança em privado", "What is NUTCADE?": "O que é o NUTCADE?", "NUTCADE is a wallet for Bitcoin, held as Cashu ecash, with an arcade built in. It runs in your browser.": "O NUTCADE é uma carteira de Bitcoin, guardado como ecash do Cashu, com um fliperama embutido. Funciona no seu navegador.", "There is no account to make, and nobody at NUTCADE can see or touch your sats.": "Não é preciso criar conta, e ninguém no NUTCADE pode ver ou tocar nos seus sats.", "What are ecash and a mint?": "O que são ecash e um mint?", "Ecash is money in the form of coins that sit on your device. A mint is a service that makes those coins and holds the Bitcoin behind them. You choose which mints to use.": "Ecash é dinheiro em forma de moedas que ficam no seu dispositivo. Um mint é um serviço que cria essas moedas e guarda o Bitcoin que as sustenta. Você escolhe quais mints usar.", "Anyone can run a mint, so only use mints you trust. A mint sees the coins you exchange with it.": "Qualquer pessoa pode operar um mint, então use apenas mints em que você confia. Um mint vê as moedas que você troca com ele.", "What if a mint closes or stops working?": "E se um mint fechar ou parar de funcionar?", "Your sats are a promise from the mint. If it closes or stops working, the ecash you hold there may not be spendable any more, and NUTCADE cannot bring it back.": "Seus sats são uma promessa do mint. Se ele fechar ou parar de funcionar, o ecash que você guarda lá pode não poder mais ser gasto, e o NUTCADE não consegue trazê-lo de volta.", "So keep only what you can afford to lose at any one mint, and spread your sats over more than one. The Mints tab shows how each mint is doing, and its report card gives it a grade.": "Por isso, deixe em cada mint só o que você pode se dar ao luxo de perder e distribua seus sats entre mais de um. A aba Mints mostra como cada mint está e o relatório dele dá uma nota.", "While a mint works, you can move sats to another one: Settings, Wallet tools, Move sats between mints.": "Enquanto um mint funciona, você pode mover sats para outro: Ajustes, Ferramentas, Mover sats entre mints.", "What are my 12 words?": "O que são minhas 12 palavras?", "They are your recovery phrase, and the only way to get your sats back if this phone is lost or its browser data is cleared. NUTCADE does not keep a copy.": "São sua frase de recuperação e a única forma de recuperar seus sats se este celular for perdido ou os dados do navegador forem apagados. O NUTCADE não guarda cópia.", "Write them on paper, in order, and keep them offline. Never type them into a website, take a screenshot or send them to anyone, including anyone who says they are NUTCADE support.": "Escreva-as no papel, em ordem, e guarde-as offline. Nunca as digite em um site, tire print nem envie a ninguém, nem mesmo a quem disser ser do suporte do NUTCADE.", "Also write down the mints you use. Restoring scans the mints you list.": "Anote também os mints que você usa. Ao restaurar, são verificados os mints que você listar.", "To practise, tap Check my 12 words in Settings, Backup. The check happens on this phone only.": "Para praticar, toque em Conferir minhas 12 palavras em Ajustes, Backup. A conferência acontece só neste celular.", "I have a new phone, or I lost mine": "Tenho um celular novo ou perdi o meu", "Open NUTCADE on the new device, tick the box and tap Restore from recovery phrase. Type your 12 words and tick the mints you used (Find my mints on Nostr can find them for you). NUTCADE scans those mints and rebuilds your balance.": "Abra o NUTCADE no novo dispositivo, marque a caixa e toque em Restaurar com frase de recuperação. Digite suas 12 palavras e marque os mints que você usou (Encontrar meus mints no Nostr pode achá-los para você). O NUTCADE verifica esses mints e reconstrói seu saldo.", "Your notes and history are not in your 12 words. They come back only from a backup file (Settings, Backup, Import backup).": "Suas notas e seu histórico não estão nas suas 12 palavras. Só voltam a partir de um arquivo de backup (Ajustes, Backup, Importar backup).", "A backup file holds your phrase and all your coins, so anyone who has it can spend your sats. Keep it private.": "Um arquivo de backup guarda sua frase e todas as suas moedas, então quem o tiver pode gastar seus sats. Mantenha-o privado.", "A payment looks stuck": "Um pagamento parece travado", "Open Settings, Wallet tools and tap Check stuck payments. A Lightning payment that fails returns your sats. One that is still waiting is tracked until the mint settles it.": "Abra Ajustes, Ferramentas e toque em Verificar pagamentos travados. Um pagamento Lightning que falha devolve seus sats. Um que ainda espera é acompanhado até o mint resolver.", "If NUTCADE closes halfway through a step, it finishes or puts it right the next time you open it.": "Se o NUTCADE fechar no meio de uma etapa, ele a conclui ou corrige na próxima vez que você abri-lo.", "If your balance looks too low, tap Find lost ecash in Settings, Backup. NUTCADE asks your mints for coins that belong to your 12 words and were never saved.": "Se o seu saldo parecer baixo demais, toque em Procurar ecash perdido em Ajustes, Backup. O NUTCADE pede aos seus mints as moedas que pertencem às suas 12 palavras e nunca foram salvas.", "Why isn't ecash mine until it is claimed?": "Por que o ecash não é meu até ser resgatado?", "A token is like cash in an envelope: whoever claims it first gets it. It is yours only once your wallet has claimed it.": "Um token é como dinheiro num envelope: quem resgatar primeiro fica com ele. Ele só é seu depois que sua carteira o resgatar.", "When you send a token, it shows as pending until the other person claims it. While it is unclaimed you can take it back with Reclaim.": "Quando você envia um token, ele aparece como pendente até a outra pessoa resgatá-lo. Enquanto não for resgatado, você pode pegá-lo de volta com Recuperar.", "Offline, ecash that people give you is saved and claimed when you are back online. Until then it is not yours yet.": "Offline, o ecash que as pessoas lhe dão é salvo e resgatado quando você voltar a ficar online. Até lá, ele ainda não é seu.", "What do fees cost?": "Quanto custam as taxas?", "A mint may charge a small fee to spend coins, and Lightning payments have a network fee. NUTCADE shows the fee before you confirm.": "Um mint pode cobrar uma pequena taxa para gastar moedas, e os pagamentos Lightning têm uma taxa de rede. O NUTCADE mostra a taxa antes de você confirmar.", "What do the PIN and the duress PIN do?": "O que fazem o PIN e o PIN de coação?", "A PIN locks NUTCADE and keeps your phrase, ecash and notes encrypted on this device. It stops someone who picks up your phone. It cannot stop malware on a device that is already compromised. If you forget it, reset the wallet and restore with your 12 words.": "Um PIN bloqueia o NUTCADE e mantém sua frase, seu ecash e suas notas criptografados neste dispositivo. Ele barra quem pegar seu celular. Não consegue barrar um malware num dispositivo já comprometido. Se você o esquecer, redefina a carteira e restaure com suas 12 palavras.", "The duress PIN is a second PIN that opens a small, separate wallet instead of yours, for when someone makes you unlock NUTCADE. It helps against a person standing in front of you. It does not help against someone who studies your phone with the app's open code.": "O PIN de coação é um segundo PIN que abre uma carteira pequena e separada no lugar da sua, para quando alguém o obrigar a desbloquear o NUTCADE. Ele ajuda contra uma pessoa diante de você. Não ajuda contra alguém que estude seu celular com o código aberto do app.", "Face ID or fingerprint opens your real wallet only, so turn it off if you rely on the duress PIN.": "Face ID ou a digital abrem só a sua carteira real, então desative-os se você conta com o PIN de coação.", "Can I use it offline?": "Posso usar offline?", "Open NUTCADE once while online and it keeps a copy, so it opens without a connection after that. Offline, you can send ecash for amounts made of the exact coins you hold.": "Abra o NUTCADE uma vez com internet e ele guarda uma cópia, então depois abre sem conexão. Offline, você pode enviar ecash em valores formados pelas moedas exatas que você tem.", "Hide my amounts": "Ocultar meus valores", "Tap your balance, or the eye button beside it, to show ••• instead of amounts on the wallet, notes and mints screens. It is remembered on this device.": "Toque no seu saldo, ou no botão de olho ao lado, para mostrar ••• no lugar dos valores nas telas de carteira, notas e mints. Isso fica lembrado neste dispositivo.", "Payment screens always show the real amount, so you know what you are about to send.": "As telas de pagamento sempre mostram o valor real, para você saber o que vai enviar.", "How do updates work?": "Como funcionam as atualizações?", "NUTCADE updates itself: the next time you open it, it loads the new version, and a note tells you what changed.": "O NUTCADE se atualiza sozinho: na próxima vez que você o abrir, ele carrega a nova versão e um aviso diz o que mudou.", "If you keep it open for days, a message says when a new version is ready. Reload when you are done: NUTCADE never reloads by itself, and never offers it in the middle of a payment.": "Se você o deixar aberto por dias, uma mensagem avisa quando uma nova versão estiver pronta. Recarregue quando terminar: o NUTCADE nunca recarrega sozinho e nunca oferece isso no meio de um pagamento.", "Keeping your wallet safe": "Como manter sua carteira segura", "The only real address is https://random21m.github.io/nutcade/. Anything else that calls itself NUTCADE is not us.": "O único endereço real é https://random21m.github.io/nutcade/. Qualquer outro que se chame NUTCADE não somos nós.", "On iPhone, add NUTCADE to your Home Screen. Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "No iPhone, adicione o NUTCADE à Tela de Início. O Safari pode apagar o armazenamento de sites que você não abre há um tempo, mas um app da Tela de Início o mantém.", "Set a PIN, keep your 12 words offline, and start with small amounts: NUTCADE is young software that has not been independently audited.": "Defina um PIN, guarde suas 12 palavras offline e comece com valores pequenos: o NUTCADE é um software jovem que não foi auditado de forma independente.", "What does NUTCADE contact? (Privacy)": "Quem o NUTCADE contata? (Privacidade)", "NUTCADE has no account, no tracking, no analytics and no ads. It contacts these services, and only for the reason given:": "O NUTCADE não tem conta, rastreamento, análise de uso nem anúncios. Ele contata estes serviços, e só pelo motivo indicado:", "Your mints: for every payment, to check that they answer, and to read their name and contact details. A mint sees the coins you exchange with it.": "Seus mints: em cada pagamento, para conferir se respondem e para ler o nome e os dados de contato deles. Um mint vê as moedas que você troca com ele.", "The mints in the Add mint list (Minibits, Cuba Bitcoin, 8333.space and two test mints), only while that list is open, to show whether they answer.": "Os mints da lista Adicionar mint (Minibits, Cuba Bitcoin, 8333.space e dois mints de teste), só enquanto essa lista está aberta, para mostrar se respondem.", "Nostr relays (relay.damus.io, nos.lol and relay.primal.net): for game challenges and payments between contacts, apps you connect with Wallet Connect, your encrypted mint list, requests you made and ecash sent to your ecash address. A contact or a payment request can name relays of its own, which are used when you send to them.": "Relays do Nostr (relay.damus.io, nos.lol e relay.primal.net): para desafios de jogos e pagamentos entre contatos, os apps que você conecta com o Wallet Connect, sua lista de mints criptografada, os pedidos que você fez e o ecash enviado ao seu endereço de ecash. Um contato ou um pedido de pagamento pode indicar relays próprios, que são usados quando você envia algo a eles.", "Two more relays (relay.nostr.band and relay.cashumints.space) are asked only when you tap Find mints people recommend.": "Outros dois relays (relay.nostr.band e relay.cashumints.space) só são consultados quando você toca em Encontrar mints recomendados.", "Coinbase, for the price and the price chart, only while Show Bitcoin price is on.": "Coinbase, para o preço e o gráfico de preços, só enquanto Mostrar preço do Bitcoin está ativado.", "npub.cash, while your Lightning address is on, and npubx.cash, when you tip from inside the app (the tip address is an npubx.cash address).": "npub.cash, enquanto seu endereço Lightning está ativado e npubx.cash, quando você dá uma gorjeta de dentro do app (o endereço de gorjetas é um endereço npubx.cash).", "The web address of any Lightning address, LNURL, voucher or payment request you pay or scan, and of a Nostr profile when you zap it. It sees that one request.": "O endereço web de qualquer endereço Lightning, LNURL, voucher ou pedido de pagamento que você pague ou escaneie, e o de um perfil do Nostr quando você faz um zap. Ele vê apenas essa solicitação.", "This website, to load NUTCADE, its QR scanner and the update check. GitHub, which hosts it, sees these requests like any website visit.": "Este site, para carregar o NUTCADE, o leitor de QR e a verificação de atualizações. O GitHub, que o hospeda, vê essas solicitações como em qualquer visita a um site.", "GitHub pages (the source, release notes and the problem report form), only when you tap a link to them.": "Páginas do GitHub (o código-fonte, as notas de versão e o formulário de relato de problemas), só quando você toca em um link para elas.", "The camera is used only while a scanner is open and the microphone only while a Listen screen is open. Nothing is recorded or sent.": "A câmera é usada só enquanto um leitor está aberto e o microfone só enquanto uma tela de Ouvir está aberta. Nada é gravado nem enviado.", "Reporting a problem": "Relatar um problema", "Reports on GitHub are public. Never paste your 12 words, your PIN, a backup file or a token into one.": "Os relatos no GitHub são públicos. Nunca cole neles suas 12 palavras, seu PIN, um arquivo de backup nem um token.", "For a security problem, use the private report link below, so that only the maintainer sees it.": "Para um problema de segurança, use o link de relato privado abaixo, para que só quem mantém o projeto veja.", "Your initials": "Suas iniciais", "Shown on your high scores and on the challenges you play. Scores you already sent to friends keep the initials they were sent with.": "Aparecem nos seus recordes e nos desafios que você joga. As pontuações que você já enviou a amigos mantêm as iniciais com que foram enviadas.", "New initials (3 letters or numbers)": "Novas iniciais (3 letras ou números)", "Also rename my past scores on this phone": "Renomear também minhas pontuações antigas neste celular", "Save initials": "Salvar iniciais", "Use exactly 3 letters or numbers.": "Use exatamente 3 letras ou números.", "Initials saved.": "Iniciais salvas.", "Arcade": "Arcade", "Details": "Detalhes", "Mint details": "Detalhes do mint", "ASKING THE MINT": "PERGUNTANDO AO MINT", "The mint did not answer, so there is nothing to show yet.": "O mint não respondeu, então ainda não há nada para mostrar.", "About this mint": "Sobre este mint", "In more detail": "Com mais detalhes", "Message from the mint": "Mensagem do mint", "Contact": "Contato", "The mint lists no contact.": "O mint não informa nenhum contato.", "Terms of service": "Termos de serviço", "The mint lists no terms.": "O mint não informa termos.", "Software": "Software", "This text was written by the mint, not by NUTCADE. Read it with care: a mint that says it is safe has not been checked by us.": "Este texto foi escrito pelo mint, não pelo NUTCADE. Leia com cuidado: um mint que diz ser seguro não foi verificado por nós.", "Extra protection: the app now refuses to run any code that is not its own, even if a bad mint or website tried to slip some in.": "Proteção extra: o app agora se recusa a executar qualquer código que não seja dele, mesmo que um mint ou site mal-intencionado tente inserir algum.", "The backup file can be protected with a password, and it now also saves contacts, settings, trophies and arcade progress.": "O arquivo de backup pode ser protegido com uma senha e agora também guarda contatos, ajustes, troféus e o progresso do arcade.", "New, optional: Back up with my phone locks your 12 words with a passkey and keeps the locked copy on Nostr relays.": "Novo e opcional: Backup com meu celular tranca suas 12 palavras com uma chave de acesso e guarda a cópia trancada em relays do Nostr.", "It also holds your contacts, settings, trophies and arcade progress.": "Também guarda seus contatos, ajustes, troféus e o progresso do arcade.", "Protect with a password": "Proteger com uma senha", "The file can only be opened with the password you choose.": "O arquivo só pode ser aberto com a senha que você escolher.", "Choose a password for the file. Anyone with the file and the password can spend your sats.": "Escolha uma senha para o arquivo. Qualquer pessoa com o arquivo e a senha pode gastar seus sats.", "Password": "Senha", "Same password again": "A mesma senha de novo", "NUTCADE can't recover a forgotten password. Your 12 words still restore your sats.": "O NUTCADE não consegue recuperar uma senha esquecida. Suas 12 palavras continuam restaurando seus sats.", "Download locked backup": "Baixar backup trancado", "Locked backup file downloaded. Keep the password safe.": "Arquivo de backup trancado baixado. Guarde bem a senha.", "Use at least 8 characters for the password.": "Use pelo menos 8 caracteres na senha.", "The two passwords don't match.": "As duas senhas não coincidem.", "Backup password": "Senha do backup", "This backup is locked with a password.": "Este backup está trancado com uma senha.", "Type the backup's password.": "Digite a senha do backup.", "Wrong password, or the file is damaged. Nothing was changed.": "Senha errada, ou o arquivo está danificado. Nada foi alterado.", "This locked backup was made by a newer NUTCADE or is damaged. Nothing was changed.": "Este backup trancado foi feito por um NUTCADE mais novo ou está danificado. Nada foi alterado.", "Back up with my phone": "Backup com meu celular", "Restore with my phone": "Restaurar com meu celular", "Locks your 12 words with a passkey (Face ID or fingerprint) and keeps the locked copy on Nostr relays. A new phone gets them back with the same passkey. Your 12 words stay your main backup.": "Tranca suas 12 palavras com uma chave de acesso (Face ID ou digital) e guarda a cópia trancada em relays do Nostr. Um celular novo as recupera com a mesma chave de acesso. Suas 12 palavras continuam sendo seu backup principal.", "Phone backup": "Backup no celular", "NOT SET UP": "NÃO CONFIGURADO", "OUT OF DATE": "DESATUALIZADO", "It holds your old 12 words. Tap Back up again to save the new ones.": "Ele guarda suas 12 palavras antigas. Toque em Fazer backup de novo para salvar as novas.", "Back up again": "Fazer backup de novo", "Remove phone backup": "Remover backup no celular", "Your Apple or Google account becomes a key to your wallet: anyone who gets into it can use the passkey to get your 12 words back. Keep that account safe, with two-step sign-in.": "Sua conta Apple ou Google vira uma chave da sua carteira: quem entrar nela pode usar a chave de acesso para recuperar suas 12 palavras. Proteja essa conta com verificação em duas etapas.", "NUTCADE makes a passkey on this phone (kept in iCloud Keychain or Google Password Manager), locks your 12 words with it and saves the locked copy on Nostr relays. No server of ours is involved.": "O NUTCADE cria uma chave de acesso neste celular (guardada nas Chaves do iCloud ou no Gerenciador de Senhas do Google), tranca suas 12 palavras com ela e guarda a cópia trancada em relays do Nostr. Nenhum servidor nosso participa.", "Keep your 12 words on paper too. They are still your main backup.": "Guarde também suas 12 palavras no papel. Elas continuam sendo seu backup principal.", "BACKED UP!": "BACKUP FEITO!", "Your 12 words are locked with your passkey and saved on {#} relay. On a new phone, tap Restore with my phone.": "Suas 12 palavras estão trancadas com sua chave de acesso e guardadas em {#} relay. Em um celular novo, toque em Restaurar com meu celular.", "Your 12 words are locked with your passkey and saved on {#} relays. On a new phone, tap Restore with my phone.": "Suas 12 palavras estão trancadas com sua chave de acesso e guardadas em {#} relays. Em um celular novo, toque em Restaurar com meu celular.", "NUTCADE asks the Nostr relays to delete the locked copy of your 12 words. A relay that is down or ignores the request can keep it, still locked with your passkey.": "O NUTCADE pede aos relays do Nostr que apaguem a cópia trancada das suas 12 palavras. Um relay fora do ar ou que ignore o pedido pode mantê-la, ainda trancada com sua chave de acesso.", "You can also delete the passkey in your password manager.": "Você também pode apagar a chave de acesso no seu gerenciador de senhas.", "REMOVING": "REMOVENDO", "RESETTING": "REDEFININDO", "Phone backup removed.": "Backup no celular removido.", "Your 12 words came from your phone backup. They are not shown here.": "Suas 12 palavras vieram do seu backup no celular. Elas não são mostradas aqui.", "Enter your PIN to back up your 12 words with your phone.": "Digite seu PIN para fazer backup das suas 12 palavras com seu celular.", "Back up with my phone isn't available right now. Try again later.": "Backup com meu celular não está disponível agora. Tente mais tarde.", "Restore with my phone isn't available right now. Try again later.": "Restaurar com meu celular não está disponível agora. Tente mais tarde.", "This phone or browser can't lock your words with a passkey. Nothing was saved. Your 12 words are still your backup.": "Este celular ou navegador não consegue trancar suas palavras com uma chave de acesso. Nada foi salvo. Suas 12 palavras continuam sendo seu backup.", "Create or restore a wallet first.": "Primeiro crie ou restaure uma carteira.", "Back up with my phone needs a connection. Try again online.": "Backup com meu celular precisa de conexão. Tente de novo quando estiver online.", "Restore with my phone needs a connection. Try again online.": "Restaurar com meu celular precisa de conexão. Tente de novo quando estiver online.", "No Nostr relay answered, so nothing was saved. Check your connection and try again.": "Nenhum relay do Nostr respondeu, então nada foi salvo. Verifique sua conexão e tente de novo.", "No Nostr relay answered, so the phone backup is still there. Try again online.": "Nenhum relay do Nostr respondeu, então o backup no celular continua lá. Tente de novo quando estiver online.", "The passkey step was cancelled. Nothing was changed.": "A etapa da chave de acesso foi cancelada. Nada foi alterado.", "That passkey isn't a NUTCADE phone backup. Nothing was changed.": "Essa chave de acesso não é um backup do NUTCADE no celular. Nada foi alterado.", "This phone or browser can't open a phone backup. Nothing was changed. Use your 12 words.": "Este celular ou navegador não consegue abrir um backup no celular. Nada foi alterado. Use suas 12 palavras.", "No Nostr relay answered. Check your connection and try again. Nothing was changed.": "Nenhum relay do Nostr respondeu. Verifique sua conexão e tente de novo. Nada foi alterado.", "No phone backup was found for this passkey. Nothing was changed.": "Nenhum backup no celular foi encontrado para esta chave de acesso. Nada foi alterado.", "This phone backup couldn't be opened with this passkey. Nothing was changed.": "Este backup no celular não pôde ser aberto com esta chave de acesso. Nada foi alterado.", "This also deletes your phone backup from the Nostr relays, so Restore with my phone will not bring this wallet back. Without your 12 words, your sats are gone for good.": "Isto também apaga seu backup no celular dos relays do Nostr, então Restaurar com meu celular não vai trazer esta carteira de volta. Sem suas 12 palavras, seus sats se perdem para sempre.", "Your phone backup holds this wallet's 12 words. If this changes them, the phone backup is out of date until you tap Back up again in Settings.": "Seu backup no celular guarda as 12 palavras desta carteira. Se isto mudá-las, o backup no celular fica desatualizado até você tocar em Fazer backup de novo nos Ajustes.", "After this, Restore with my phone will not bring this wallet back. Keep your 12 words.": "Depois disto, Restaurar com meu celular não vai trazer esta carteira de volta. Guarde suas 12 palavras.", "A phone backup, if you made one, is not deleted by this reset: it stays on the Nostr relays, and Restore with my phone can bring the wallet back.": "Um backup no celular, se você fez um, não é apagado por esta redefinição: ele fica nos relays do Nostr, e Restaurar com meu celular pode trazer a carteira de volta.", "The copy on the Nostr relays for this passkey holds other 12 words, saved from another phone or another wallet. Replacing it means that phone backup is lost.": "A cópia nos relays do Nostr para esta chave de acesso guarda outras 12 palavras, salvas de outro celular ou outra carteira. Substituí-la significa perder esse backup no celular.", "Replace anyway": "Substituir mesmo assim", "Your phone backup's passkey wasn't found, or the step was cancelled. If you deleted the passkey, tap Remove phone backup, then back up again.": "A chave de acesso do seu backup no celular não foi encontrada, ou a etapa foi cancelada. Se você apagou a chave de acesso, toque em Remover backup no celular e depois faça o backup de novo.", "Contacts: {#} added, {#} skipped (the same name or address is already here, or it wasn't valid).": "Contatos: {#} adicionados, {#} ignorados (já existe um com o mesmo nome ou endereço, ou não era válido)."});
  if (D.de) add(D.de, {"Updated to v{#}": "Auf v{#} aktualisiert", "What's new": "Was ist neu", "What's new in v{#}": "Neu in v{#}", "New version v{#} is ready. Reload when you're done.": "Die neue Version v{#} ist bereit. Lade neu, wenn Du fertig bist.", "New version v{#} is ready.": "Die neue Version v{#} ist bereit.", "Reload now": "Jetzt neu laden", "Finish what you're doing first, then reload.": "Schließe zuerst ab, was Du gerade tust, und lade dann neu.", "Time to check your 12 words. It takes a minute and nothing leaves this phone.": "Zeit, Deine 12 Wörter zu prüfen. Es dauert eine Minute, und nichts verlässt dieses Handy.", "Check now": "Jetzt prüfen", "Send all": "Alles senden", "Stays at this mint": "Bleibt bei diesem Mint", "Leaves your balance": "Verlässt Dein Guthaben", "Network fee": "Netzwerkgebühr", "Create token for {#} SAT": "Token über {#} SAT erstellen", "Send all: everything at this mint, less the mint's fee.": "Alles senden: alles bei diesem Mint, abzüglich der Mint-Gebühr.", "Send all: everything at this mint, less the fees.": "Alles senden: alles bei diesem Mint, abzüglich der Gebühren.", "Your balance at this mint changed, so nothing was sent. Tap Send all again to see the new amount.": "Dein Guthaben bei diesem Mint hat sich geändert, deshalb wurde nichts gesendet. Tippe noch einmal auf Alles senden, um den neuen Betrag zu sehen.", "Nothing to send: this mint holds {#} SAT.": "Nichts zu senden: Dieser Mint hält {#} SAT.", "The fees ({#} SAT) are as much as this mint's balance of {#} SAT, so nothing can be sent from it.": "Die Gebühren ({#} SAT) sind so hoch wie das Guthaben dieses Mints von {#} SAT, deshalb kann von dort nichts gesendet werden.", "After the fees, {#} SAT would be left to send, less than the smallest payment allowed here ({#} SAT). Nothing was sent.": "Nach den Gebühren blieben {#} SAT zum Senden, weniger als die kleinste hier erlaubte Zahlung ({#} SAT). Es wurde nichts gesendet.", "This mint takes at most {#} coins per request, and it holds {#} of yours, so Send all can't be used there. Type an amount instead.": "Dieser Mint nimmt höchstens {#} Münzen pro Anfrage, und er hält {#} von Deinen, deshalb geht Alles senden dort nicht. Gib stattdessen einen Betrag ein.", "Send all isn't available with this mint right now. Type an amount instead.": "Alles senden ist mit diesem Mint gerade nicht möglich. Gib stattdessen einen Betrag ein.", "This mint didn't say what the payment costs. Nothing was sent.": "Dieser Mint hat nicht gesagt, was die Zahlung kostet. Es wurde nichts gesendet.", "The fees kept changing, so Send all could not settle on an amount. Nothing was sent. Try again.": "Die Gebühren haben sich ständig geändert, deshalb konnte Alles senden keinen Betrag festlegen. Es wurde nichts gesendet. Versuche es noch einmal.", "The most this mint pays out at once is {#} SAT, so the rest stays at this mint.": "Dieser Mint zahlt höchstens {#} SAT auf einmal aus, deshalb bleibt der Rest bei diesem Mint.", "The most this address or mint takes in one payment is {#} SAT, so the rest stays at this mint.": "Diese Adresse oder dieser Mint nimmt höchstens {#} SAT in einer Zahlung, deshalb bleibt der Rest bei diesem Mint.", "Send all makes a token anyone can claim. Turn off the lock first, or type an amount.": "Alles senden erstellt einen Token, den jeder einlösen kann. Schalte zuerst die Sperre aus oder gib einen Betrag ein.", "Send all needs the mint, and you're offline. Try again online.": "Alles senden braucht den Mint, und Du bist offline. Versuche es online noch einmal.", "Paste the Bitcoin address first.": "Füge zuerst die Bitcoin-Adresse ein.", "Send all: send everything at a mint in one go, as an ecash token, to a Lightning address or on-chain. NUTCADE works out the fees and shows exactly what will leave before anything is sent.": "Alles senden: Sende alles bei einem Mint auf einmal, als Ecash-Token, an eine Lightning-Adresse oder on-chain. NUTCADE berechnet die Gebühren und zeigt genau, was abgeht, bevor etwas gesendet wird.", "A receive note for an on-chain address nobody has paid yet is now hidden until a payment arrives. The price chart link now opens Settings at Show Bitcoin price.": "Eine Empfangsnotiz für eine On-Chain-Adresse, die noch niemand bezahlt hat, ist jetzt bis zum Zahlungseingang ausgeblendet. Der Link beim Preisdiagramm öffnet jetzt die Optionen bei Bitcoin-Preis anzeigen.", "Send all uses only the mint you picked: your other mints are not touched. The spending limit and your PIN apply as for any payment.": "Alles senden nutzt nur den Mint, den Du gewählt hast: Deine anderen Mints bleiben unberührt. Das Ausgabenlimit und Deine PIN gelten wie bei jeder Zahlung.", "NUTCADE can't save your wallet.": "NUTCADE kann Deine Wallet nicht speichern.", "This browser's storage is full, so your newest coins and changes exist only on this screen. Don't close or reload NUTCADE.": "Der Speicher dieses Browsers ist voll, deshalb gibt es Deine neuesten Münzen und Änderungen nur auf diesem Bildschirm. Schließe NUTCADE nicht und lade es nicht neu.", "Download a backup file now to keep a copy. Then free up space on this phone and tap Try again.": "Lade jetzt eine Backup-Datei herunter, um eine Kopie zu haben. Gib dann Speicherplatz auf diesem Handy frei und tippe auf Nochmal versuchen.", "If NUTCADE closes before it can save, use Find lost ecash in Settings, Backup: your 12 words bring those coins back.": "Wenn NUTCADE schließt, bevor es speichern kann, nutze „Verlorenes Ecash finden“ unter Einstellungen, Backup: Deine 12 Wörter holen diese Münzen zurück.", "Storage for NUTCADE is {#}% full.": "Der Speicher für NUTCADE ist zu {#}% voll.", "Soon it may not be able to save your wallet. Download a backup file now, and free up space on this phone.": "Bald kann es Deine Wallet vielleicht nicht mehr speichern. Lade jetzt eine Backup-Datei herunter und gib Speicherplatz auf diesem Handy frei.", "Download a backup file now and then to keep a copy.": "Lade ab und zu eine Backup-Datei herunter, um eine Kopie zu haben.", "Storage used by NUTCADE": "Von NUTCADE belegter Speicher", "{#} MB / {#} MB ({#}%)": "{#} MB / {#} MB ({#}%)", "Add NUTCADE to your Home Screen, or Safari may delete this wallet.": "Füge NUTCADE zu Deinem Home-Bildschirm hinzu, sonst kann Safari diese Wallet löschen.", "Show me how": "Zeig mir wie", "Not today": "Heute nicht", "Add to Home Screen": "Zum Home-Bildschirm", "Open NUTCADE in Safari.": "Öffne NUTCADE in Safari.", "Tap Share (the square with an arrow; on newer iOS, tap ••• first).": "Tippe auf Teilen (das Quadrat mit dem Pfeil; bei neuerem iOS zuerst auf •••).", "Tap Add to Home Screen, then Add.": "Tippe auf Zum Home-Bildschirm und dann auf Hinzufügen.", "From now on, open NUTCADE from the new icon.": "Öffne NUTCADE ab jetzt über das neue Symbol.", "In Settings, Backup, tap Download backup and keep the file.": "Tippe unter Optionen, Backup auf Backup herunterladen und bewahre die Datei auf.", "The new icon keeps a wallet of its own and starts empty. Open it, tick the box, tap Create a new wallet and finish its setup steps (its words are replaced when you import), then tap Import backup in Settings, Backup and choose the file. Your wallet comes back as it was in the file. Then use only the icon.": "Das neue Symbol hat eine eigene Wallet und startet leer. Öffne es, setze das Häkchen, tippe auf Neue Wallet erstellen und schließe die Schritte ab (ihre Wörter werden beim Import ersetzt), dann unter Optionen, Backup auf Backup importieren und wähle die Datei. Deine Wallet kommt so zurück, wie sie in der Datei war. Nutze danach nur noch das Symbol.", "No backup file? Tap Restore from recovery phrase instead and enter your 12 words. That brings back the ecash made from your words at your mints, but not tokens still waiting to be claimed, locked ecash, ecash that didn't come from your words, or payments still in progress: settle those in Safari first.": "Keine Backup-Datei? Tippe auf Mit 12 Wörtern wiederherstellen und gib Deine 12 Wörter ein. Das holt das Ecash zurück, das mit Deinen Wörtern bei Deinen Mints erstellt wurde, aber keine Tokens, die noch auf Einlösung warten, kein gesperrtes Ecash, kein Ecash, das nicht aus Deinen Wörtern stammt, und keine laufenden Zahlungen: Erledige diese vorher in Safari.", "Then set up your wallet from the new icon.": "Richte dann Deine Wallet über das neue Symbol ein.", "Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "Safari kann den Speicher von Websites löschen, die Du eine Weile nicht geöffnet hast, aber eine App auf dem Home-Bildschirm behält ihn.", "Steps for every device": "Schritte für jedes Gerät", "NUTCADE couldn't save your wallet: storage is full. Keep it open and read the notice on the wallet screen.": "NUTCADE konnte Deine Wallet nicht speichern: Der Speicher ist voll. Lass es offen und lies den Hinweis auf dem Wallet-Bildschirm.", "Can't lock now: your wallet isn't saved yet. Free up space first.": "Sperren geht gerade nicht: Deine Wallet ist noch nicht gespeichert. Gib zuerst Speicherplatz frei.", "Can't reload now: your wallet isn't saved yet. Free up space first.": "Neu laden geht gerade nicht: Deine Wallet ist noch nicht gespeichert. Gib zuerst Speicherplatz frei.", "Still can't save. Free up more space on this phone, then try again.": "Speichern geht immer noch nicht. Gib mehr Speicherplatz auf diesem Handy frei und versuch es dann noch einmal.", "Saved. Your wallet is stored on this device again.": "Gespeichert. Deine Wallet ist wieder auf diesem Gerät gespeichert.", "This browser won't save data, so NUTCADE stopped before using your recovery phrase. Free up space, then try again.": "Dieser Browser speichert keine Daten, deshalb hat NUTCADE angehalten, bevor es Deine Wiederherstellungsphrase benutzt. Gib Speicherplatz frei und versuch es dann noch einmal.", "This browser won't save data, so the PIN was not removed. Free up space and try again.": "Dieser Browser speichert keine Daten, deshalb wurde die PIN nicht entfernt. Gib Speicherplatz frei und versuch es noch einmal.", "This browser won't save data. Free up space and try again.": "Dieser Browser speichert keine Daten. Gib Speicherplatz frei und versuch es noch einmal.", "If this browser can't save your wallet (storage full), NUTCADE now says so in red on the wallet screen, with what to do, instead of failing silently.": "Wenn dieser Browser Deine Wallet nicht speichern kann (Speicher voll), sagt NUTCADE das jetzt rot auf dem Wallet-Bildschirm, mit dem, was zu tun ist, statt still zu scheitern.", "Settings, Backup shows how much storage NUTCADE uses, and the wallet screen warns when it is 70% and 90% full.": "Einstellungen, Backup zeigt, wie viel Speicher NUTCADE belegt, und der Wallet-Bildschirm warnt bei 70% und 90%.", "On iPhone, the wallet screen reminds you to add NUTCADE to your Home Screen, so Safari does not delete your wallet.": "Auf dem iPhone erinnert Dich der Wallet-Bildschirm daran, NUTCADE zu Deinem Home-Bildschirm hinzuzufügen, damit Safari Deine Wallet nicht löscht.", "Choose how many recent notes the home screen shows, from 0 to 6, in Settings, Look & sound.": "Wähle, wie viele letzte Notizen der Startbildschirm zeigt, von 0 bis 6, unter Einstellungen, Aussehen & Ton.", "The Hall of Fame shows each game's full name.": "Die Ruhmeshalle zeigt den vollen Namen jedes Spiels.", "New game: Nut Bowl, top-down arcade football. Pick a play, run it or throw it, and beat the clock.": "Neues Spiel: Nut Bowl, American Football von oben. Spielzug wählen, laufen oder werfen, und die Uhr schlagen.", "The arcade now has twelve cabinets, and Nut Bowl can be the Daily Challenge.": "Die Spielhalle hat jetzt zwölf Automaten, und Nut Bowl kann die Tages-Challenge sein.", "A very large balance no longer cuts off the SAT label on small screens.": "Ein sehr hohes Guthaben schneidet die Beschriftung SAT auf kleinen Bildschirmen nicht mehr ab.", "Claiming a saved ecash note now shows its amount once, and a second open tab can no longer start a second claim.": "Beim Einlösen eines gespeicherten Ecash erscheint der Betrag nur einmal, und ein zweiter offener Tab kann keine zweite Einlösung mehr starten.", "A deposit that was finished again after an interrupted answer now says \"+X received\" like any other arrival.": "Eine Einzahlung, die nach einer unterbrochenen Antwort erneut abgeschlossen wurde, zeigt jetzt wie jeder andere Eingang „+X erhalten“.", "Saved ecash claimed after you come back online no longer shows a toast next to its own arrival notice.": "Gespeichertes Ecash, das nach der Rückkehr online eingelöst wird, zeigt keinen Hinweis mehr neben seiner eigenen Eingangsmeldung.", "Recent notes on the home screen": "Letzte Notizen auf dem Startbildschirm", "How many of your latest notes the home screen lists. All notes always shows the rest. Kept on this device.": "Wie viele Deiner letzten Notizen der Startbildschirm zeigt. Alle Notizen zeigt immer den Rest. Wird auf diesem Gerät gespeichert.", "Can't reach the mint right now. Try again in a moment.": "Der Mint ist gerade nicht erreichbar. Versuch es gleich noch einmal.", "A token you saved while offline is now claimed once, even if you tap Claim now while NUTCADE claims it too.": "Ein Token, den Du offline gespeichert hast, wird jetzt nur einmal eingelöst, auch wenn Du auf „Jetzt einlösen“ tippst, während NUTCADE ihn ebenfalls einlöst.", "The home screen shows your last 2 notes. All notes shows the rest.": "Der Startbildschirm zeigt Deine letzten 2 Notizen. Alle Notizen zeigt den Rest.", "Hide amounts also hides amounts in arrival notices.": "Beträge ausblenden blendet auch die Beträge in den Eingangsmeldungen aus.", "Hide amounts": "Beträge ausblenden", "Show amounts": "Beträge anzeigen", "Tap to hide amounts": "Tippen, um Beträge auszublenden", "Tap to show amounts": "Tippen, um Beträge anzuzeigen", "Shows ••• instead of amounts on the wallet, notes and mints screens. You can also tap your balance. Payment screens always show the real amount.": "Zeigt ••• statt der Beträge auf den Bildschirmen Wallet, Notizen und Mints. Du kannst auch auf Dein Guthaben tippen. Zahlungsbildschirme zeigen immer den echten Betrag.", "12 words last checked": "12 Wörter zuletzt geprüft", "NEVER": "NIE", "Check my 12 words": "Meine 12 Wörter prüfen", "Last backup file": "Letzte Backup-Datei", "A backup file only holds what your wallet held on the day you made it.": "Eine Backup-Datei enthält nur das, was Deine Wallet an dem Tag hatte, an dem Du sie erstellt hast.", "Check your 12 words": "Prüfe Deine 12 Wörter", "Type these words from your paper copy, not from memory.": "Tippe diese Wörter von Deiner Papierkopie ab, nicht aus dem Gedächtnis.", "This check happens on this phone only. Your words are not shown, saved or sent anywhere.": "Diese Prüfung findet nur auf diesem Handy statt. Deine Wörter werden nicht angezeigt, gespeichert oder irgendwohin gesendet.", "Word #{#}": "Wort Nr. {#}", "Check": "Prüfen", "Show the words again": "Wörter erneut anzeigen", "Not now": "Jetzt nicht", "Later": "Später", "Don't remind me again": "Nicht mehr erinnern", "Word #{#} doesn't match. Check your paper, or show the words again.": "Wort Nr. {#} stimmt nicht überein. Sieh auf Deinem Papier nach oder zeige die Wörter erneut an.", "Your 12 words check out. NUTCADE will ask again in about six months.": "Deine 12 Wörter stimmen. NUTCADE fragt in etwa sechs Monaten wieder.", "OK. You can still check your words any time in Settings, Backup.": "OK. Du kannst Deine Wörter jederzeit unter Optionen, Backup prüfen.", "Notices when money arrives: a deposit, a token, a payment to your address. NUTCADE tells you, and shows what came in while you were away.": "Hinweise, wenn Geld ankommt: eine Einzahlung, ein Token, eine Zahlung an Deine Adresse. NUTCADE sagt es Dir und zeigt, was in Deiner Abwesenheit eingegangen ist.", "Change your initials any time, in the Arcade or in Settings.": "Ändere Deine Initialen jederzeit, in der Spielhalle oder in den Einstellungen.", "Help & FAQ in Settings: short answers, offline, in five languages.": "Hilfe & FAQ unter Optionen: kurze Antworten, offline, in fünf Sprachen.", "A check of your 12 words a week after your backup, and again twice a year. It happens on your phone only.": "Eine Prüfung Deiner 12 Wörter eine Woche nach Deinem Backup und danach zweimal im Jahr. Sie findet nur auf Deinem Handy statt.", "Settings, Backup shows when you last made a backup file.": "Unter Optionen, Backup siehst Du, wann Du zuletzt eine Backup-Datei erstellt hast.", "Each mint's contact, terms and description, under Details in Mints.": "Kontakt, Bedingungen und Beschreibung jedes Mints, unter Details bei Mints.", "Hide amounts: tap your balance to show ••• instead of amounts.": "Beträge ausblenden: Tippe auf Dein Guthaben, um ••• statt der Beträge zu zeigen.", "A note after each update, and a message when a new version is ready to load.": "Ein Hinweis nach jedem Update und eine Meldung, wenn eine neue Version zum Laden bereit ist.", "A Privacy section that lists every service NUTCADE contacts, and why.": "Ein Datenschutz-Abschnitt, der jeden Dienst auflistet, den NUTCADE kontaktiert, und warum.", "Every release has signed checksums, so you can check that the files are the real ones.": "Jede Version hat signierte Prüfsummen, damit Du prüfen kannst, dass die Dateien echt sind.", "Release page on GitHub": "Release-Seite auf GitHub", "Checksums": "Prüfsummen", "Done": "Fertig", "Check for a new version": "Nach neuer Version suchen", "CHECKING": "PRÜFE", "You have the newest version.": "Du hast die neueste Version.", "Couldn't check right now.": "Gerade nicht möglich zu prüfen.", "Twelve cabinets of free play once you're in.": "Zwölf Automaten zum freien Spielen, sobald Du drin bist.", "Help": "Hilfe", "Help & FAQ": "Hilfe & FAQ", "Short answers: what ecash is, a new phone, a stuck payment and what NUTCADE contacts. It works offline.": "Kurze Antworten: was Ecash ist, ein neues Handy, eine hängende Zahlung und wen NUTCADE kontaktiert. Funktioniert offline.", "Report a problem": "Problem melden", "Report a security problem privately": "Sicherheitsproblem vertraulich melden", "What is NUTCADE?": "Was ist NUTCADE?", "NUTCADE is a wallet for Bitcoin, held as Cashu ecash, with an arcade built in. It runs in your browser.": "NUTCADE ist eine Wallet für Bitcoin, gehalten als Cashu-Ecash, mit einer eingebauten Spielhalle. Sie läuft in Deinem Browser.", "There is no account to make, and nobody at NUTCADE can see or touch your sats.": "Es gibt kein Konto anzulegen, und niemand bei NUTCADE kann Deine Sats sehen oder anfassen.", "What are ecash and a mint?": "Was sind Ecash und ein Mint?", "Ecash is money in the form of coins that sit on your device. A mint is a service that makes those coins and holds the Bitcoin behind them. You choose which mints to use.": "Ecash ist Geld in Form von Münzen, die auf Deinem Gerät liegen. Ein Mint ist ein Dienst, der diese Münzen ausgibt und das Bitcoin dahinter verwahrt. Du wählst, welche Mints Du nutzt.", "Anyone can run a mint, so only use mints you trust. A mint sees the coins you exchange with it.": "Jeder kann einen Mint betreiben, nutze also nur Mints, denen Du vertraust. Ein Mint sieht die Münzen, die Du mit ihm tauschst.", "What if a mint closes or stops working?": "Was, wenn ein Mint schließt oder nicht mehr funktioniert?", "Your sats are a promise from the mint. If it closes or stops working, the ecash you hold there may not be spendable any more, and NUTCADE cannot bring it back.": "Deine Sats sind ein Versprechen des Mints. Wenn er schließt oder nicht mehr funktioniert, lässt sich das Ecash dort vielleicht nicht mehr ausgeben, und NUTCADE kann es nicht zurückholen.", "So keep only what you can afford to lose at any one mint, and spread your sats over more than one. The Mints tab shows how each mint is doing, and its report card gives it a grade.": "Behalte deshalb bei jedem Mint nur, was Du verschmerzen kannst, und verteile Deine Sats auf mehr als einen. Der Reiter Mints zeigt, wie es jedem Mint geht, und sein Zeugnis gibt ihm eine Note.", "While a mint works, you can move sats to another one: Settings, Wallet tools, Move sats between mints.": "Solange ein Mint funktioniert, kannst Du Sats zu einem anderen verschieben: Optionen, Wallet-Werkzeuge, Sats zwischen Mints verschieben.", "What are my 12 words?": "Was sind meine 12 Wörter?", "They are your recovery phrase, and the only way to get your sats back if this phone is lost or its browser data is cleared. NUTCADE does not keep a copy.": "Sie sind Deine Wiederherstellungsphrase und der einzige Weg, Deine Sats zurückzubekommen, wenn dieses Handy verloren geht oder seine Browserdaten gelöscht werden. NUTCADE behält keine Kopie.", "Write them on paper, in order, and keep them offline. Never type them into a website, take a screenshot or send them to anyone, including anyone who says they are NUTCADE support.": "Schreibe sie der Reihe nach auf Papier und bewahre sie offline auf. Gib sie nie auf einer Website ein, mache keinen Screenshot und sende sie niemandem, auch nicht jemandem, der sich als NUTCADE-Support ausgibt.", "Also write down the mints you use. Restoring scans the mints you list.": "Notiere auch die Mints, die Du nutzt. Beim Wiederherstellen werden die Mints abgesucht, die Du angibst.", "To practise, tap Check my 12 words in Settings, Backup. The check happens on this phone only.": "Zum Üben tippe unter Optionen, Backup auf Meine 12 Wörter prüfen. Die Prüfung findet nur auf diesem Handy statt.", "I have a new phone, or I lost mine": "Ich habe ein neues Handy oder meins ist weg", "Open NUTCADE on the new device, tick the box and tap Restore from recovery phrase. Type your 12 words and tick the mints you used (Find my mints on Nostr can find them for you). NUTCADE scans those mints and rebuilds your balance.": "Öffne NUTCADE auf dem neuen Gerät, setze den Haken und tippe auf Mit 12 Wörtern wiederherstellen. Gib Deine 12 Wörter ein und wähle die Mints aus, die Du genutzt hast (Meine Mints auf Nostr finden kann sie für Dich finden). NUTCADE durchsucht diese Mints und baut Dein Guthaben wieder auf.", "Your notes and history are not in your 12 words. They come back only from a backup file (Settings, Backup, Import backup).": "Deine Notizen und Dein Verlauf stecken nicht in Deinen 12 Wörtern. Sie kommen nur aus einer Backup-Datei zurück (Optionen, Backup, Backup importieren).", "A backup file holds your phrase and all your coins, so anyone who has it can spend your sats. Keep it private.": "Eine Backup-Datei enthält Deine Phrase und alle Deine Münzen, wer sie hat, kann Deine Sats ausgeben. Halte sie privat.", "A payment looks stuck": "Eine Zahlung hängt anscheinend", "Open Settings, Wallet tools and tap Check stuck payments. A Lightning payment that fails returns your sats. One that is still waiting is tracked until the mint settles it.": "Öffne Optionen, Wallet-Werkzeuge und tippe auf Hängende Zahlungen prüfen. Eine fehlgeschlagene Lightning-Zahlung gibt Deine Sats zurück. Eine, die noch wartet, wird verfolgt, bis der Mint sie abschließt.", "If NUTCADE closes halfway through a step, it finishes or puts it right the next time you open it.": "Wenn NUTCADE mitten in einem Schritt schließt, bringt es ihn beim nächsten Öffnen zu Ende oder stellt ihn richtig.", "If your balance looks too low, tap Find lost ecash in Settings, Backup. NUTCADE asks your mints for coins that belong to your 12 words and were never saved.": "Wenn Dein Guthaben zu niedrig aussieht, tippe unter Optionen, Backup auf Verlorenes Ecash finden. NUTCADE fragt Deine Mints nach Münzen, die zu Deinen 12 Wörtern gehören und nie gespeichert wurden.", "Why isn't ecash mine until it is claimed?": "Warum gehört Ecash mir erst, wenn es eingelöst ist?", "A token is like cash in an envelope: whoever claims it first gets it. It is yours only once your wallet has claimed it.": "Ein Token ist wie Bargeld im Umschlag: Wer es zuerst einlöst, bekommt es. Es gehört Dir erst, wenn Deine Wallet es eingelöst hat.", "When you send a token, it shows as pending until the other person claims it. While it is unclaimed you can take it back with Reclaim.": "Wenn Du einen Token sendest, steht er als ausstehend da, bis die andere Person ihn einlöst. Solange er nicht eingelöst ist, kannst Du ihn mit Zurückholen zurückholen.", "Offline, ecash that people give you is saved and claimed when you are back online. Until then it is not yours yet.": "Offline wird Ecash, das Dir jemand gibt, gespeichert und eingelöst, sobald Du wieder online bist. Bis dahin gehört es Dir noch nicht.", "What do fees cost?": "Was kosten Gebühren?", "A mint may charge a small fee to spend coins, and Lightning payments have a network fee. NUTCADE shows the fee before you confirm.": "Ein Mint kann für das Ausgeben von Münzen eine kleine Gebühr verlangen, und Lightning-Zahlungen haben eine Netzwerkgebühr. NUTCADE zeigt die Gebühr, bevor Du bestätigst.", "What do the PIN and the duress PIN do?": "Was machen die PIN und die Zwangs-PIN?", "A PIN locks NUTCADE and keeps your phrase, ecash and notes encrypted on this device. It stops someone who picks up your phone. It cannot stop malware on a device that is already compromised. If you forget it, reset the wallet and restore with your 12 words.": "Eine PIN sperrt NUTCADE und hält Deine Phrase, Dein Ecash und Deine Notizen auf diesem Gerät verschlüsselt. Sie hält jemanden auf, der Dein Handy in die Hand nimmt. Gegen Schadsoftware auf einem bereits kompromittierten Gerät hilft sie nicht. Wenn Du sie vergisst, setze die Wallet zurück und stelle sie mit Deinen 12 Wörtern wieder her.", "The duress PIN is a second PIN that opens a small, separate wallet instead of yours, for when someone makes you unlock NUTCADE. It helps against a person standing in front of you. It does not help against someone who studies your phone with the app's open code.": "Die Zwangs-PIN ist eine zweite PIN, die statt Deiner eigenen eine kleine, getrennte Wallet öffnet, für den Fall, dass Dich jemand zwingt, NUTCADE zu entsperren. Sie hilft gegen eine Person, die vor Dir steht. Sie hilft nicht gegen jemanden, der Dein Handy mit dem offenen Code der App untersucht.", "Face ID or fingerprint opens your real wallet only, so turn it off if you rely on the duress PIN.": "Face ID oder Fingerabdruck öffnen nur Deine echte Wallet, schalte sie also aus, wenn Du Dich auf die Zwangs-PIN verlässt.", "Can I use it offline?": "Kann ich es offline nutzen?", "Open NUTCADE once while online and it keeps a copy, so it opens without a connection after that. Offline, you can send ecash for amounts made of the exact coins you hold.": "Öffne NUTCADE einmal online, dann behält es eine Kopie und öffnet danach auch ohne Verbindung. Offline kannst Du Ecash für Beträge senden, die sich aus Deinen genauen Münzen zusammensetzen.", "Hide my amounts": "Meine Beträge ausblenden", "Tap your balance, or the eye button beside it, to show ••• instead of amounts on the wallet, notes and mints screens. It is remembered on this device.": "Tippe auf Dein Guthaben oder auf den Augen-Button daneben, um ••• statt der Beträge auf den Bildschirmen Wallet, Notizen und Mints zu zeigen. Das merkt sich dieses Gerät.", "Payment screens always show the real amount, so you know what you are about to send.": "Zahlungsbildschirme zeigen immer den echten Betrag, damit Du weißt, was Du gleich sendest.", "How do updates work?": "Wie funktionieren Updates?", "NUTCADE updates itself: the next time you open it, it loads the new version, and a note tells you what changed.": "NUTCADE aktualisiert sich selbst: Beim nächsten Öffnen lädt es die neue Version, und ein Hinweis sagt Dir, was sich geändert hat.", "If you keep it open for days, a message says when a new version is ready. Reload when you are done: NUTCADE never reloads by itself, and never offers it in the middle of a payment.": "Wenn Du es tagelang offen lässt, meldet ein Hinweis, wann eine neue Version bereit ist. Lade neu, wenn Du fertig bist: NUTCADE lädt nie von selbst neu und bietet es nie mitten in einer Zahlung an.", "Keeping your wallet safe": "So hältst Du Deine Wallet sicher", "The only real address is https://random21m.github.io/nutcade/. Anything else that calls itself NUTCADE is not us.": "Die einzige echte Adresse ist https://random21m.github.io/nutcade/. Alles andere, was sich NUTCADE nennt, sind nicht wir.", "On iPhone, add NUTCADE to your Home Screen. Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "Füge NUTCADE auf dem iPhone zum Home-Bildschirm hinzu. Safari kann den Speicher von Websites löschen, die Du länger nicht geöffnet hast, eine App vom Home-Bildschirm behält ihn.", "Set a PIN, keep your 12 words offline, and start with small amounts: NUTCADE is young software that has not been independently audited.": "Lege eine PIN fest, bewahre Deine 12 Wörter offline auf und beginne mit kleinen Beträgen: NUTCADE ist junge Software, die nicht unabhängig geprüft wurde.", "What does NUTCADE contact? (Privacy)": "Wen kontaktiert NUTCADE? (Datenschutz)", "NUTCADE has no account, no tracking, no analytics and no ads. It contacts these services, and only for the reason given:": "NUTCADE hat kein Konto, kein Tracking, keine Analyse und keine Werbung. Es kontaktiert diese Dienste, und nur aus dem genannten Grund:", "Your mints: for every payment, to check that they answer, and to read their name and contact details. A mint sees the coins you exchange with it.": "Deine Mints: bei jeder Zahlung, um zu prüfen, ob sie antworten, und um ihren Namen und ihre Kontaktdaten zu lesen. Ein Mint sieht die Münzen, die Du mit ihm tauschst.", "The mints in the Add mint list (Minibits, Cuba Bitcoin, 8333.space and two test mints), only while that list is open, to show whether they answer.": "Die Mints in der Liste Mint hinzufügen (Minibits, Cuba Bitcoin, 8333.space und zwei Test-Mints), nur solange diese Liste offen ist, um zu zeigen, ob sie antworten.", "Nostr relays (relay.damus.io, nos.lol and relay.primal.net): for game challenges and payments between contacts, apps you connect with Wallet Connect, your encrypted mint list, requests you made and ecash sent to your ecash address. A contact or a payment request can name relays of its own, which are used when you send to them.": "Nostr-Relays (relay.damus.io, nos.lol und relay.primal.net): für Spiel-Herausforderungen und Zahlungen zwischen Kontakten, Apps, die Du per Wallet Connect verbindest, Deine verschlüsselte Mint-Liste, Anfragen, die Du gestellt hast, und Ecash, das an Deine Ecash-Adresse gesendet wird. Ein Kontakt oder eine Zahlungsanfrage kann eigene Relays nennen, die genutzt werden, wenn Du ihnen etwas sendest.", "Two more relays (relay.nostr.band and relay.cashumints.space) are asked only when you tap Find mints people recommend.": "Zwei weitere Relays (relay.nostr.band und relay.cashumints.space) werden nur gefragt, wenn Du auf Von anderen empfohlene Mints finden tippst.", "Coinbase, for the price and the price chart, only while Show Bitcoin price is on.": "Coinbase, für den Preis und das Preisdiagramm, nur solange Bitcoin-Preis anzeigen eingeschaltet ist.", "npub.cash, while your Lightning address is on, and npubx.cash, when you tip from inside the app (the tip address is an npubx.cash address).": "npub.cash, solange Deine Lightning-Adresse eingeschaltet ist und npubx.cash, wenn Du in der App ein Trinkgeld gibst (die Trinkgeld-Adresse ist eine npubx.cash-Adresse).", "The web address of any Lightning address, LNURL, voucher or payment request you pay or scan, and of a Nostr profile when you zap it. It sees that one request.": "Die Webadresse jeder Lightning-Adresse, jedes LNURL, Gutscheins oder jeder Zahlungsanfrage, die Du bezahlst oder scannst, und die eines Nostr-Profils, wenn Du ihm einen Zap sendest. Sie sieht diese eine Anfrage.", "This website, to load NUTCADE, its QR scanner and the update check. GitHub, which hosts it, sees these requests like any website visit.": "Diese Website, um NUTCADE, den QR-Scanner und die Update-Prüfung zu laden. GitHub, das sie hostet, sieht diese Anfragen wie bei jedem Website-Besuch.", "GitHub pages (the source, release notes and the problem report form), only when you tap a link to them.": "GitHub-Seiten (der Quellcode, die Release-Hinweise und das Formular zum Melden von Problemen), nur wenn Du auf einen Link dorthin tippst.", "The camera is used only while a scanner is open and the microphone only while a Listen screen is open. Nothing is recorded or sent.": "Die Kamera wird nur genutzt, solange ein Scanner offen ist, und das Mikrofon nur, solange ein Zuhören-Bildschirm offen ist. Nichts wird aufgenommen oder gesendet.", "Reporting a problem": "Ein Problem melden", "Reports on GitHub are public. Never paste your 12 words, your PIN, a backup file or a token into one.": "Meldungen auf GitHub sind öffentlich. Füge niemals Deine 12 Wörter, Deine PIN, eine Backup-Datei oder einen Token ein.", "For a security problem, use the private report link below, so that only the maintainer sees it.": "Nutze bei einem Sicherheitsproblem den privaten Meldelink unten, damit nur der Maintainer ihn sieht.", "Your initials": "Deine Initialen", "Shown on your high scores and on the challenges you play. Scores you already sent to friends keep the initials they were sent with.": "Werden bei Deinen Highscores und bei den Herausforderungen angezeigt, die Du spielst. Ergebnisse, die Du Freunden schon geschickt hast, behalten die Initialen, mit denen sie gesendet wurden.", "New initials (3 letters or numbers)": "Neue Initialen (3 Buchstaben oder Zahlen)", "Also rename my past scores on this phone": "Auch meine bisherigen Ergebnisse auf diesem Handy umbenennen", "Save initials": "Initialen speichern", "Use exactly 3 letters or numbers.": "Nutze genau 3 Buchstaben oder Zahlen.", "Initials saved.": "Initialen gespeichert.", "Arcade": "Arcade", "Details": "Details", "Mint details": "Mint-Details", "ASKING THE MINT": "FRAGE DEN MINT", "The mint did not answer, so there is nothing to show yet.": "Der Mint hat nicht geantwortet, daher gibt es noch nichts zu zeigen.", "About this mint": "Über diesen Mint", "In more detail": "Genauer", "Message from the mint": "Nachricht vom Mint", "Contact": "Kontakt", "The mint lists no contact.": "Der Mint nennt keinen Kontakt.", "Terms of service": "Nutzungsbedingungen", "The mint lists no terms.": "Der Mint nennt keine Bedingungen.", "Software": "Software", "This text was written by the mint, not by NUTCADE. Read it with care: a mint that says it is safe has not been checked by us.": "Dieser Text stammt vom Mint, nicht von NUTCADE. Lies ihn mit Vorsicht: Ein Mint, der sagt, er sei sicher, wurde von uns nicht geprüft.", "Extra protection: the app now refuses to run any code that is not its own, even if a bad mint or website tried to slip some in.": "Zusätzlicher Schutz: Die App führt jetzt keinen fremden Code mehr aus, selbst wenn ein schlechter Mint oder eine schlechte Website versucht, welchen einzuschleusen.", "The backup file can be protected with a password, and it now also saves contacts, settings, trophies and arcade progress.": "Die Backup-Datei kann mit einem Passwort geschützt werden und speichert jetzt auch Kontakte, Optionen, Trophäen und den Arcade-Fortschritt.", "New, optional: Back up with my phone locks your 12 words with a passkey and keeps the locked copy on Nostr relays.": "Neu und optional: Mit meinem Handy sichern sperrt Deine 12 Wörter mit einem Passkey und legt die gesperrte Kopie auf Nostr-Relays ab.", "It also holds your contacts, settings, trophies and arcade progress.": "Sie enthält auch Deine Kontakte, Optionen, Trophäen und den Arcade-Fortschritt.", "Protect with a password": "Mit einem Passwort schützen", "The file can only be opened with the password you choose.": "Die Datei lässt sich nur mit dem Passwort öffnen, das Du wählst.", "Choose a password for the file. Anyone with the file and the password can spend your sats.": "Wähle ein Passwort für die Datei. Wer die Datei und das Passwort hat, kann Deine Sats ausgeben.", "Password": "Passwort", "Same password again": "Dasselbe Passwort noch einmal", "NUTCADE can't recover a forgotten password. Your 12 words still restore your sats.": "NUTCADE kann ein vergessenes Passwort nicht wiederherstellen. Deine 12 Wörter stellen Deine Sats weiterhin wieder her.", "Download locked backup": "Gesperrtes Backup herunterladen", "Locked backup file downloaded. Keep the password safe.": "Gesperrte Backup-Datei heruntergeladen. Bewahre das Passwort sicher auf.", "Use at least 8 characters for the password.": "Nutze mindestens 8 Zeichen für das Passwort.", "The two passwords don't match.": "Die beiden Passwörter stimmen nicht überein.", "Backup password": "Backup-Passwort", "This backup is locked with a password.": "Dieses Backup ist mit einem Passwort gesperrt.", "Type the backup's password.": "Gib das Passwort des Backups ein.", "Wrong password, or the file is damaged. Nothing was changed.": "Falsches Passwort, oder die Datei ist beschädigt. Es wurde nichts geändert.", "This locked backup was made by a newer NUTCADE or is damaged. Nothing was changed.": "Dieses gesperrte Backup stammt von einem neueren NUTCADE oder ist beschädigt. Es wurde nichts geändert.", "Back up with my phone": "Mit meinem Handy sichern", "Restore with my phone": "Mit meinem Handy wiederherstellen", "Locks your 12 words with a passkey (Face ID or fingerprint) and keeps the locked copy on Nostr relays. A new phone gets them back with the same passkey. Your 12 words stay your main backup.": "Sperrt Deine 12 Wörter mit einem Passkey (Face ID oder Fingerabdruck) und legt die gesperrte Kopie auf Nostr-Relays ab. Ein neues Handy holt sie mit demselben Passkey zurück. Deine 12 Wörter bleiben Dein wichtigstes Backup.", "Phone backup": "Handy-Backup", "NOT SET UP": "NICHT EINGERICHTET", "OUT OF DATE": "VERALTET", "It holds your old 12 words. Tap Back up again to save the new ones.": "Es enthält Deine alten 12 Wörter. Tippe auf Erneut sichern, um die neuen zu speichern.", "Back up again": "Erneut sichern", "Remove phone backup": "Handy-Backup entfernen", "Your Apple or Google account becomes a key to your wallet: anyone who gets into it can use the passkey to get your 12 words back. Keep that account safe, with two-step sign-in.": "Dein Apple- oder Google-Konto wird zu einem Schlüssel für Deine Wallet: Wer hineinkommt, kann mit dem Passkey Deine 12 Wörter zurückholen. Schütze dieses Konto mit Zwei-Faktor-Anmeldung.", "NUTCADE makes a passkey on this phone (kept in iCloud Keychain or Google Password Manager), locks your 12 words with it and saves the locked copy on Nostr relays. No server of ours is involved.": "NUTCADE erstellt einen Passkey auf diesem Handy (im iCloud-Schlüsselbund oder im Google Passwortmanager), sperrt damit Deine 12 Wörter und legt die gesperrte Kopie auf Nostr-Relays ab. Kein Server von uns ist beteiligt.", "Keep your 12 words on paper too. They are still your main backup.": "Bewahre Deine 12 Wörter auch auf Papier auf. Sie bleiben Dein wichtigstes Backup.", "BACKED UP!": "GESICHERT!", "Your 12 words are locked with your passkey and saved on {#} relay. On a new phone, tap Restore with my phone.": "Deine 12 Wörter sind mit Deinem Passkey gesperrt und auf {#} Relay gespeichert. Tippe auf einem neuen Handy auf Mit meinem Handy wiederherstellen.", "Your 12 words are locked with your passkey and saved on {#} relays. On a new phone, tap Restore with my phone.": "Deine 12 Wörter sind mit Deinem Passkey gesperrt und auf {#} Relays gespeichert. Tippe auf einem neuen Handy auf Mit meinem Handy wiederherstellen.", "NUTCADE asks the Nostr relays to delete the locked copy of your 12 words. A relay that is down or ignores the request can keep it, still locked with your passkey.": "NUTCADE bittet die Nostr-Relays, die gesperrte Kopie Deiner 12 Wörter zu löschen. Ein Relay, das gerade nicht erreichbar ist oder die Bitte ignoriert, kann sie behalten, weiterhin mit Deinem Passkey gesperrt.", "You can also delete the passkey in your password manager.": "Du kannst den Passkey auch in Deinem Passwortmanager löschen.", "REMOVING": "ENTFERNE", "RESETTING": "SETZE ZURÜCK", "Phone backup removed.": "Handy-Backup entfernt.", "Your 12 words came from your phone backup. They are not shown here.": "Deine 12 Wörter stammen aus Deinem Handy-Backup. Sie werden hier nicht angezeigt.", "Enter your PIN to back up your 12 words with your phone.": "Gib Deine PIN ein, um Deine 12 Wörter mit Deinem Handy zu sichern.", "Back up with my phone isn't available right now. Try again later.": "Mit meinem Handy sichern ist gerade nicht verfügbar. Versuche es später noch einmal.", "Restore with my phone isn't available right now. Try again later.": "Mit meinem Handy wiederherstellen ist gerade nicht verfügbar. Versuche es später noch einmal.", "This phone or browser can't lock your words with a passkey. Nothing was saved. Your 12 words are still your backup.": "Dieses Handy oder dieser Browser kann Deine Wörter nicht mit einem Passkey sperren. Es wurde nichts gespeichert. Deine 12 Wörter bleiben Dein Backup.", "Create or restore a wallet first.": "Erstelle oder stelle zuerst eine Wallet wieder her.", "Back up with my phone needs a connection. Try again online.": "Mit meinem Handy sichern braucht eine Verbindung. Versuche es online noch einmal.", "Restore with my phone needs a connection. Try again online.": "Mit meinem Handy wiederherstellen braucht eine Verbindung. Versuche es online noch einmal.", "No Nostr relay answered, so nothing was saved. Check your connection and try again.": "Kein Nostr-Relay hat geantwortet, deshalb wurde nichts gespeichert. Prüfe Deine Verbindung und versuche es noch einmal.", "No Nostr relay answered, so the phone backup is still there. Try again online.": "Kein Nostr-Relay hat geantwortet, deshalb ist das Handy-Backup noch da. Versuche es online noch einmal.", "The passkey step was cancelled. Nothing was changed.": "Der Passkey-Schritt wurde abgebrochen. Es wurde nichts geändert.", "That passkey isn't a NUTCADE phone backup. Nothing was changed.": "Dieser Passkey ist kein NUTCADE-Handy-Backup. Es wurde nichts geändert.", "This phone or browser can't open a phone backup. Nothing was changed. Use your 12 words.": "Dieses Handy oder dieser Browser kann kein Handy-Backup öffnen. Es wurde nichts geändert. Nutze Deine 12 Wörter.", "No Nostr relay answered. Check your connection and try again. Nothing was changed.": "Kein Nostr-Relay hat geantwortet. Prüfe Deine Verbindung und versuche es noch einmal. Es wurde nichts geändert.", "No phone backup was found for this passkey. Nothing was changed.": "Für diesen Passkey wurde kein Handy-Backup gefunden. Es wurde nichts geändert.", "This phone backup couldn't be opened with this passkey. Nothing was changed.": "Dieses Handy-Backup ließ sich mit diesem Passkey nicht öffnen. Es wurde nichts geändert.", "This also deletes your phone backup from the Nostr relays, so Restore with my phone will not bring this wallet back. Without your 12 words, your sats are gone for good.": "Das löscht auch Dein Handy-Backup von den Nostr-Relays, Mit meinem Handy wiederherstellen bringt diese Wallet dann nicht zurück. Ohne Deine 12 Wörter sind Deine Sats für immer verloren.", "Your phone backup holds this wallet's 12 words. If this changes them, the phone backup is out of date until you tap Back up again in Settings.": "Dein Handy-Backup enthält die 12 Wörter dieser Wallet. Ändert dieser Schritt sie, ist das Handy-Backup veraltet, bis Du in den Optionen auf Erneut sichern tippst.", "After this, Restore with my phone will not bring this wallet back. Keep your 12 words.": "Danach bringt Mit meinem Handy wiederherstellen diese Wallet nicht zurück. Bewahre Deine 12 Wörter auf.", "A phone backup, if you made one, is not deleted by this reset: it stays on the Nostr relays, and Restore with my phone can bring the wallet back.": "Ein Handy-Backup, falls Du eines gemacht hast, wird durch dieses Zurücksetzen nicht gelöscht: Es bleibt auf den Nostr-Relays, und Mit meinem Handy wiederherstellen kann die Wallet zurückholen.", "The copy on the Nostr relays for this passkey holds other 12 words, saved from another phone or another wallet. Replacing it means that phone backup is lost.": "Die Kopie auf den Nostr-Relays für diesen Passkey enthält andere 12 Wörter, gespeichert von einem anderen Handy oder einer anderen Wallet. Wenn Du sie ersetzt, ist dieses Handy-Backup verloren.", "Replace anyway": "Trotzdem ersetzen", "Your phone backup's passkey wasn't found, or the step was cancelled. If you deleted the passkey, tap Remove phone backup, then back up again.": "Der Passkey Deines Handy-Backups wurde nicht gefunden, oder der Schritt wurde abgebrochen. Wenn Du den Passkey gelöscht hast, tippe auf Handy-Backup entfernen und sichere dann erneut.", "Contacts: {#} added, {#} skipped (the same name or address is already here, or it wasn't valid).": "Kontakte: {#} hinzugefügt, {#} übersprungen (derselbe Name oder dieselbe Adresse ist schon da, oder er war ungültig)."});
  if (D.fr) add(D.fr, {"Updated to v{#}": "Mis à jour vers la v{#}", "What's new": "Nouveautés", "What's new in v{#}": "Nouveautés de la v{#}", "New version v{#} is ready. Reload when you're done.": "La nouvelle version v{#} est prête. Rechargez quand vous avez fini.", "New version v{#} is ready.": "La nouvelle version v{#} est prête.", "Reload now": "Recharger maintenant", "Finish what you're doing first, then reload.": "Terminez d'abord ce que vous faites, puis rechargez.", "Time to check your 12 words. It takes a minute and nothing leaves this phone.": "C'est le moment de vérifier vos 12 mots. Cela prend une minute et rien ne quitte ce téléphone.", "Check now": "Vérifier maintenant", "Send all": "Tout envoyer", "Stays at this mint": "Reste sur ce mint", "Leaves your balance": "Quitte votre solde", "Network fee": "Frais de réseau", "Create token for {#} SAT": "Créer un jeton de {#} SAT", "Send all: everything at this mint, less the mint's fee.": "Tout envoyer : tout ce qui est sur ce mint, moins les frais du mint.", "Send all: everything at this mint, less the fees.": "Tout envoyer : tout ce qui est sur ce mint, moins les frais.", "Your balance at this mint changed, so nothing was sent. Tap Send all again to see the new amount.": "Votre solde sur ce mint a changé, donc rien n'a été envoyé. Touchez à nouveau Tout envoyer pour voir le nouveau montant.", "Nothing to send: this mint holds {#} SAT.": "Rien à envoyer : ce mint détient {#} SAT.", "The fees ({#} SAT) are as much as this mint's balance of {#} SAT, so nothing can be sent from it.": "Les frais ({#} SAT) atteignent le solde de ce mint, {#} SAT, donc rien ne peut en être envoyé.", "After the fees, {#} SAT would be left to send, less than the smallest payment allowed here ({#} SAT). Nothing was sent.": "Après les frais, il resterait {#} SAT à envoyer, moins que le plus petit paiement permis ici ({#} SAT). Rien n'a été envoyé.", "This mint takes at most {#} coins per request, and it holds {#} of yours, so Send all can't be used there. Type an amount instead.": "Ce mint accepte au plus {#} pièces par requête et il détient {#} des vôtres, donc Tout envoyer n'y est pas possible. Saisissez plutôt un montant.", "Send all isn't available with this mint right now. Type an amount instead.": "Tout envoyer n'est pas disponible avec ce mint pour l'instant. Saisissez plutôt un montant.", "This mint didn't say what the payment costs. Nothing was sent.": "Ce mint n'a pas indiqué ce que coûte le paiement. Rien n'a été envoyé.", "The fees kept changing, so Send all could not settle on an amount. Nothing was sent. Try again.": "Les frais n'arrêtaient pas de changer, donc Tout envoyer n'a pas pu fixer de montant. Rien n'a été envoyé. Réessayez.", "The most this mint pays out at once is {#} SAT, so the rest stays at this mint.": "Ce mint paie au plus {#} SAT en une fois, donc le reste reste sur ce mint.", "The most this address or mint takes in one payment is {#} SAT, so the rest stays at this mint.": "Cette adresse ou ce mint accepte au plus {#} SAT en un paiement, donc le reste reste sur ce mint.", "Send all makes a token anyone can claim. Turn off the lock first, or type an amount.": "Tout envoyer crée un jeton que n'importe qui peut réclamer. Désactivez d'abord le verrou, ou saisissez un montant.", "Send all needs the mint, and you're offline. Try again online.": "Tout envoyer a besoin du mint, et vous êtes hors ligne. Réessayez une fois en ligne.", "Paste the Bitcoin address first.": "Collez d'abord l'adresse Bitcoin.", "Send all: send everything at a mint in one go, as an ecash token, to a Lightning address or on-chain. NUTCADE works out the fees and shows exactly what will leave before anything is sent.": "Tout envoyer : envoyez tout ce qui est sur un mint en une fois, en jeton ecash, vers une adresse Lightning ou on-chain. NUTCADE calcule les frais et montre exactement ce qui va partir avant tout envoi.", "A receive note for an on-chain address nobody has paid yet is now hidden until a payment arrives. The price chart link now opens Settings at Show Bitcoin price.": "Une note de réception pour une adresse on-chain que personne n'a payée est maintenant masquée jusqu'à l'arrivée d'un paiement. Le lien du graphique des prix ouvre maintenant les Réglages à Afficher le prix du Bitcoin.", "Send all uses only the mint you picked: your other mints are not touched. The spending limit and your PIN apply as for any payment.": "Tout envoyer n'utilise que le mint choisi : vos autres mints ne sont pas touchés. La limite de dépenses et votre PIN s'appliquent comme pour tout paiement.", "NUTCADE can't save your wallet.": "NUTCADE ne peut pas enregistrer votre portefeuille.", "This browser's storage is full, so your newest coins and changes exist only on this screen. Don't close or reload NUTCADE.": "Le stockage de ce navigateur est plein, donc vos pièces et changements les plus récents n'existent que sur cet écran. Ne fermez pas et ne rechargez pas NUTCADE.", "Download a backup file now to keep a copy. Then free up space on this phone and tap Try again.": "Téléchargez maintenant un fichier de sauvegarde pour garder une copie. Libérez ensuite de l'espace sur ce téléphone et touchez Réessayer.", "If NUTCADE closes before it can save, use Find lost ecash in Settings, Backup: your 12 words bring those coins back.": "Si NUTCADE se ferme avant de pouvoir enregistrer, utilisez Retrouver l'ecash perdu dans Réglages, Sauvegarde : vos 12 mots ramènent ces pièces.", "Storage for NUTCADE is {#}% full.": "Le stockage de NUTCADE est plein à {#} %.", "Soon it may not be able to save your wallet. Download a backup file now, and free up space on this phone.": "Bientôt, il pourrait ne plus pouvoir enregistrer votre portefeuille. Téléchargez maintenant un fichier de sauvegarde et libérez de l'espace sur ce téléphone.", "Download a backup file now and then to keep a copy.": "Téléchargez de temps en temps un fichier de sauvegarde pour garder une copie.", "Storage used by NUTCADE": "Stockage utilisé par NUTCADE", "{#} MB / {#} MB ({#}%)": "{#} Mo / {#} Mo ({#} %)", "Add NUTCADE to your Home Screen, or Safari may delete this wallet.": "Ajoutez NUTCADE à votre écran d'accueil, sinon Safari peut supprimer ce portefeuille.", "Show me how": "Montrez-moi comment", "Not today": "Pas aujourd'hui", "Add to Home Screen": "Sur l'écran d'accueil", "Open NUTCADE in Safari.": "Ouvrez NUTCADE dans Safari.", "Tap Share (the square with an arrow; on newer iOS, tap ••• first).": "Touchez Partager (le carré avec une flèche ; sur les iOS récents, touchez d'abord •••).", "Tap Add to Home Screen, then Add.": "Touchez Sur l'écran d'accueil, puis Ajouter.", "From now on, open NUTCADE from the new icon.": "Désormais, ouvrez NUTCADE depuis la nouvelle icône.", "In Settings, Backup, tap Download backup and keep the file.": "Dans Réglages, Sauvegarde, touchez Télécharger la sauvegarde et gardez le fichier.", "The new icon keeps a wallet of its own and starts empty. Open it, tick the box, tap Create a new wallet and finish its setup steps (its words are replaced when you import), then tap Import backup in Settings, Backup and choose the file. Your wallet comes back as it was in the file. Then use only the icon.": "La nouvelle icône a son propre portefeuille et démarre vide. Ouvrez-la, cochez la case, touchez Créer un nouveau portefeuille et terminez ses étapes (ses mots sont remplacés à l'importation), puis touchez Importer une sauvegarde dans Réglages, Sauvegarde et choisissez le fichier. Votre portefeuille revient tel qu'il était dans le fichier. Ensuite, utilisez uniquement l'icône.", "No backup file? Tap Restore from recovery phrase instead and enter your 12 words. That brings back the ecash made from your words at your mints, but not tokens still waiting to be claimed, locked ecash, ecash that didn't come from your words, or payments still in progress: settle those in Safari first.": "Pas de fichier de sauvegarde ? Touchez Restaurer avec la phrase de récupération et saisissez vos 12 mots. Cela ramène l'ecash créé avec vos mots chez vos mints, mais pas les jetons qui attendent encore d'être réclamés, l'ecash verrouillé, l'ecash qui ne vient pas de vos mots ni les paiements en cours : réglez-les d'abord dans Safari.", "Then set up your wallet from the new icon.": "Configurez ensuite votre portefeuille depuis la nouvelle icône.", "Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "Safari peut effacer le stockage des sites que vous n'avez pas ouverts depuis un moment, mais une app de l'écran d'accueil le conserve.", "Steps for every device": "Étapes pour chaque appareil", "NUTCADE couldn't save your wallet: storage is full. Keep it open and read the notice on the wallet screen.": "NUTCADE n'a pas pu enregistrer votre portefeuille : le stockage est plein. Gardez-le ouvert et lisez l'avis sur l'écran du portefeuille.", "Can't lock now: your wallet isn't saved yet. Free up space first.": "Impossible de verrouiller maintenant : votre portefeuille n'est pas encore enregistré. Libérez d'abord de l'espace.", "Can't reload now: your wallet isn't saved yet. Free up space first.": "Impossible de recharger maintenant : votre portefeuille n'est pas encore enregistré. Libérez d'abord de l'espace.", "Still can't save. Free up more space on this phone, then try again.": "Toujours impossible d'enregistrer. Libérez plus d'espace sur ce téléphone, puis réessayez.", "Saved. Your wallet is stored on this device again.": "Enregistré. Votre portefeuille est de nouveau stocké sur cet appareil.", "This browser won't save data, so NUTCADE stopped before using your recovery phrase. Free up space, then try again.": "Ce navigateur n'enregistre pas les données, donc NUTCADE s'est arrêté avant d'utiliser votre phrase de récupération. Libérez de l'espace, puis réessayez.", "This browser won't save data, so the PIN was not removed. Free up space and try again.": "Ce navigateur n'enregistre pas les données, donc le PIN n'a pas été supprimé. Libérez de l'espace et réessayez.", "This browser won't save data. Free up space and try again.": "Ce navigateur n'enregistre pas les données. Libérez de l'espace et réessayez.", "If this browser can't save your wallet (storage full), NUTCADE now says so in red on the wallet screen, with what to do, instead of failing silently.": "Si ce navigateur ne peut pas enregistrer votre portefeuille (stockage plein), NUTCADE le dit maintenant en rouge sur l'écran du portefeuille, avec ce qu'il faut faire, au lieu d'échouer en silence.", "Settings, Backup shows how much storage NUTCADE uses, and the wallet screen warns when it is 70% and 90% full.": "Réglages, Sauvegarde affiche le stockage utilisé par NUTCADE, et l'écran du portefeuille avertit quand il est plein à 70 % et à 90 %.", "On iPhone, the wallet screen reminds you to add NUTCADE to your Home Screen, so Safari does not delete your wallet.": "Sur iPhone, l'écran du portefeuille vous rappelle d'ajouter NUTCADE à votre écran d'accueil, pour que Safari ne supprime pas votre portefeuille.", "Choose how many recent notes the home screen shows, from 0 to 6, in Settings, Look & sound.": "Choisissez combien de notes récentes l'écran d'accueil affiche, de 0 à 6, dans Réglages, Apparence et son.", "The Hall of Fame shows each game's full name.": "Le Hall of Fame affiche le nom complet de chaque jeu.", "New game: Nut Bowl, top-down arcade football. Pick a play, run it or throw it, and beat the clock.": "Nouveau jeu : Nut Bowl, football américain arcade vu de dessus. Choisissez un jeu, courez ou lancez, et battez la montre.", "The arcade now has twelve cabinets, and Nut Bowl can be the Daily Challenge.": "La salle d'arcade a maintenant douze bornes, et Nut Bowl peut être le défi du jour.", "A very large balance no longer cuts off the SAT label on small screens.": "Un très gros solde ne coupe plus l'étiquette SAT sur les petits écrans.", "Claiming a saved ecash note now shows its amount once, and a second open tab can no longer start a second claim.": "Réclamer un ecash enregistré n'affiche plus le montant qu'une fois, et un deuxième onglet ouvert ne peut plus lancer une seconde réclamation.", "A deposit that was finished again after an interrupted answer now says \"+X received\" like any other arrival.": "Un dépôt terminé à nouveau après une réponse interrompue affiche désormais « +X reçu » comme toute autre arrivée.", "Saved ecash claimed after you come back online no longer shows a toast next to its own arrival notice.": "L'ecash enregistré réclamé au retour en ligne n'affiche plus de message à côté de sa propre notification d'arrivée.", "Recent notes on the home screen": "Notes récentes sur l'écran d'accueil", "How many of your latest notes the home screen lists. All notes always shows the rest. Kept on this device.": "Combien de vos dernières notes l'écran d'accueil affiche. Toutes les notes affiche toujours le reste. Conservé sur cet appareil.", "Can't reach the mint right now. Try again in a moment.": "Impossible de joindre le mint pour le moment. Réessayez dans un instant.", "A token you saved while offline is now claimed once, even if you tap Claim now while NUTCADE claims it too.": "Un jeton enregistré hors ligne n'est plus réclamé qu'une seule fois, même si vous touchez « Réclamer maintenant » pendant que NUTCADE le réclame aussi.", "The home screen shows your last 2 notes. All notes shows the rest.": "L'écran d'accueil affiche vos 2 dernières notes. Toutes les notes affiche le reste.", "Hide amounts also hides amounts in arrival notices.": "Masquer les montants masque aussi les montants dans les avis d'arrivée.", "Hide amounts": "Masquer les montants", "Show amounts": "Afficher les montants", "Tap to hide amounts": "Touchez pour masquer les montants", "Tap to show amounts": "Touchez pour afficher les montants", "Shows ••• instead of amounts on the wallet, notes and mints screens. You can also tap your balance. Payment screens always show the real amount.": "Affiche ••• à la place des montants sur les écrans Portefeuille, Notes et Mints. Vous pouvez aussi toucher votre solde. Les écrans de paiement montrent toujours le vrai montant.", "12 words last checked": "12 mots vérifiés pour la dernière fois", "NEVER": "JAMAIS", "Check my 12 words": "Vérifier mes 12 mots", "Last backup file": "Dernier fichier de sauvegarde", "A backup file only holds what your wallet held on the day you made it.": "Un fichier de sauvegarde ne contient que ce que votre portefeuille contenait le jour où vous l'avez fait.", "Check your 12 words": "Vérifiez vos 12 mots", "Type these words from your paper copy, not from memory.": "Saisissez ces mots d'après votre copie papier, pas de mémoire.", "This check happens on this phone only. Your words are not shown, saved or sent anywhere.": "Cette vérification se fait uniquement sur ce téléphone. Vos mots ne sont ni affichés, ni enregistrés, ni envoyés nulle part.", "Word #{#}": "Mot n° {#}", "Check": "Vérifier", "Show the words again": "Afficher à nouveau les mots", "Not now": "Pas maintenant", "Later": "Plus tard", "Don't remind me again": "Ne plus me le rappeler", "Word #{#} doesn't match. Check your paper, or show the words again.": "Le mot n° {#} ne correspond pas. Vérifiez votre papier ou affichez à nouveau les mots.", "Your 12 words check out. NUTCADE will ask again in about six months.": "Vos 12 mots sont corrects. NUTCADE vous le redemandera dans environ six mois.", "OK. You can still check your words any time in Settings, Backup.": "D'accord. Vous pouvez toujours vérifier vos mots depuis Réglages, Sauvegarde.", "Notices when money arrives: a deposit, a token, a payment to your address. NUTCADE tells you, and shows what came in while you were away.": "Des avis quand de l'argent arrive : un dépôt, un jeton, un paiement à votre adresse. NUTCADE vous le dit et montre ce qui est arrivé pendant votre absence.", "Change your initials any time, in the Arcade or in Settings.": "Changez vos initiales à tout moment, dans la Salle d'arcade ou dans les Réglages.", "Help & FAQ in Settings: short answers, offline, in five languages.": "Aide et FAQ dans Réglages : réponses courtes, hors ligne, en cinq langues.", "A check of your 12 words a week after your backup, and again twice a year. It happens on your phone only.": "Une vérification de vos 12 mots une semaine après votre sauvegarde, puis deux fois par an. Elle se fait uniquement sur votre téléphone.", "Settings, Backup shows when you last made a backup file.": "Réglages, Sauvegarde indique quand vous avez fait votre dernier fichier de sauvegarde.", "Each mint's contact, terms and description, under Details in Mints.": "Le contact, les conditions et la description de chaque mint, sous Détails dans Mints.", "Hide amounts: tap your balance to show ••• instead of amounts.": "Masquer les montants : touchez votre solde pour afficher ••• à la place des montants.", "A note after each update, and a message when a new version is ready to load.": "Une note après chaque mise à jour, et un message quand une nouvelle version est prête à être chargée.", "A Privacy section that lists every service NUTCADE contacts, and why.": "Une section Confidentialité qui liste chaque service que NUTCADE contacte, et pourquoi.", "Every release has signed checksums, so you can check that the files are the real ones.": "Chaque version a des sommes de contrôle signées, pour vérifier que les fichiers sont les vrais.", "Release page on GitHub": "Page de la version sur GitHub", "Checksums": "Sommes de contrôle", "Done": "Terminé", "Check for a new version": "Chercher une nouvelle version", "CHECKING": "VÉRIFICATION", "You have the newest version.": "Vous avez la version la plus récente.", "Couldn't check right now.": "Impossible de vérifier pour le moment.", "Twelve cabinets of free play once you're in.": "Douze bornes de jeu gratuit dès que vous êtes dedans.", "Help": "Aide", "Help & FAQ": "Aide et FAQ", "Short answers: what ecash is, a new phone, a stuck payment and what NUTCADE contacts. It works offline.": "Réponses courtes : ce qu'est l'ecash, un nouveau téléphone, un paiement bloqué et qui NUTCADE contacte. Fonctionne hors ligne.", "Report a problem": "Signaler un problème", "Report a security problem privately": "Signaler un problème de sécurité en privé", "What is NUTCADE?": "Qu'est-ce que NUTCADE ?", "NUTCADE is a wallet for Bitcoin, held as Cashu ecash, with an arcade built in. It runs in your browser.": "NUTCADE est un portefeuille pour Bitcoin, détenu sous forme d'ecash Cashu, avec une salle d'arcade intégrée. Il fonctionne dans votre navigateur.", "There is no account to make, and nobody at NUTCADE can see or touch your sats.": "Il n'y a aucun compte à créer, et personne chez NUTCADE ne peut voir ou toucher vos sats.", "What are ecash and a mint?": "Que sont l'ecash et un mint ?", "Ecash is money in the form of coins that sit on your device. A mint is a service that makes those coins and holds the Bitcoin behind them. You choose which mints to use.": "L'ecash est de l'argent sous forme de pièces qui se trouvent sur votre appareil. Un mint est un service qui crée ces pièces et détient le Bitcoin qui est derrière. Vous choisissez les mints à utiliser.", "Anyone can run a mint, so only use mints you trust. A mint sees the coins you exchange with it.": "N'importe qui peut faire tourner un mint, n'utilisez donc que des mints en qui vous avez confiance. Un mint voit les pièces que vous échangez avec lui.", "What if a mint closes or stops working?": "Et si un mint ferme ou cesse de fonctionner ?", "Your sats are a promise from the mint. If it closes or stops working, the ecash you hold there may not be spendable any more, and NUTCADE cannot bring it back.": "Vos sats sont une promesse du mint. S'il ferme ou cesse de fonctionner, l'ecash que vous y détenez peut ne plus être dépensable, et NUTCADE ne peut pas le récupérer.", "So keep only what you can afford to lose at any one mint, and spread your sats over more than one. The Mints tab shows how each mint is doing, and its report card gives it a grade.": "Ne gardez donc, chez chaque mint, que ce que vous pouvez vous permettre de perdre, et répartissez vos sats sur plusieurs. L'onglet Mints montre l'état de chaque mint, et son bulletin lui donne une note.", "While a mint works, you can move sats to another one: Settings, Wallet tools, Move sats between mints.": "Tant qu'un mint fonctionne, vous pouvez déplacer des sats vers un autre : Réglages, Outils, Déplacer des sats entre mints.", "What are my 12 words?": "Que sont mes 12 mots ?", "They are your recovery phrase, and the only way to get your sats back if this phone is lost or its browser data is cleared. NUTCADE does not keep a copy.": "C'est votre phrase de récupération, et le seul moyen de retrouver vos sats si ce téléphone est perdu ou si les données de son navigateur sont effacées. NUTCADE n'en garde aucune copie.", "Write them on paper, in order, and keep them offline. Never type them into a website, take a screenshot or send them to anyone, including anyone who says they are NUTCADE support.": "Écrivez-les sur papier, dans l'ordre, et gardez-les hors ligne. Ne les saisissez jamais sur un site web, ne faites pas de capture d'écran et ne les envoyez à personne, même à quelqu'un qui se dit du support NUTCADE.", "Also write down the mints you use. Restoring scans the mints you list.": "Notez aussi les mints que vous utilisez. La restauration analyse les mints que vous listez.", "To practise, tap Check my 12 words in Settings, Backup. The check happens on this phone only.": "Pour vous entraîner, touchez Vérifier mes 12 mots dans Réglages, Sauvegarde. La vérification se fait uniquement sur ce téléphone.", "I have a new phone, or I lost mine": "J'ai un nouveau téléphone, ou j'ai perdu le mien", "Open NUTCADE on the new device, tick the box and tap Restore from recovery phrase. Type your 12 words and tick the mints you used (Find my mints on Nostr can find them for you). NUTCADE scans those mints and rebuilds your balance.": "Ouvrez NUTCADE sur le nouvel appareil, cochez la case et touchez Restaurer avec la phrase de récupération. Saisissez vos 12 mots et cochez les mints utilisés (Trouver mes mints sur Nostr peut les retrouver pour vous). NUTCADE analyse ces mints et reconstruit votre solde.", "Your notes and history are not in your 12 words. They come back only from a backup file (Settings, Backup, Import backup).": "Vos notes et votre historique ne sont pas dans vos 12 mots. Ils ne reviennent qu'avec un fichier de sauvegarde (Réglages, Sauvegarde, Importer une sauvegarde).", "A backup file holds your phrase and all your coins, so anyone who has it can spend your sats. Keep it private.": "Un fichier de sauvegarde contient votre phrase et toutes vos pièces, donc quiconque l'a peut dépenser vos sats. Gardez-le privé.", "A payment looks stuck": "Un paiement semble bloqué", "Open Settings, Wallet tools and tap Check stuck payments. A Lightning payment that fails returns your sats. One that is still waiting is tracked until the mint settles it.": "Ouvrez Réglages, Outils et touchez Vérifier les paiements bloqués. Un paiement Lightning qui échoue rend vos sats. Un paiement encore en attente est suivi jusqu'à ce que le mint le règle.", "If NUTCADE closes halfway through a step, it finishes or puts it right the next time you open it.": "Si NUTCADE se ferme au milieu d'une étape, il la termine ou la corrige à la prochaine ouverture.", "If your balance looks too low, tap Find lost ecash in Settings, Backup. NUTCADE asks your mints for coins that belong to your 12 words and were never saved.": "Si votre solde semble trop bas, touchez Retrouver l'ecash perdu dans Réglages, Sauvegarde. NUTCADE demande à vos mints les pièces qui appartiennent à vos 12 mots et n'ont jamais été enregistrées.", "Why isn't ecash mine until it is claimed?": "Pourquoi l'ecash n'est-il à moi qu'une fois réclamé ?", "A token is like cash in an envelope: whoever claims it first gets it. It is yours only once your wallet has claimed it.": "Un token, c'est comme de l'argent dans une enveloppe : celui qui le réclame en premier l'obtient. Il n'est à vous qu'une fois que votre portefeuille l'a réclamé.", "When you send a token, it shows as pending until the other person claims it. While it is unclaimed you can take it back with Reclaim.": "Quand vous envoyez un token, il reste en attente jusqu'à ce que l'autre personne le réclame. Tant qu'il n'est pas réclamé, vous pouvez le reprendre avec Reprendre.", "Offline, ecash that people give you is saved and claimed when you are back online. Until then it is not yours yet.": "Hors ligne, l'ecash qu'on vous donne est enregistré puis réclamé quand vous êtes de nouveau en ligne. D'ici là, il n'est pas encore à vous.", "What do fees cost?": "Combien coûtent les frais ?", "A mint may charge a small fee to spend coins, and Lightning payments have a network fee. NUTCADE shows the fee before you confirm.": "Un mint peut prélever de petits frais pour dépenser des pièces, et les paiements Lightning ont des frais de réseau. NUTCADE affiche les frais avant que vous confirmiez.", "What do the PIN and the duress PIN do?": "À quoi servent le code PIN et le code PIN de contrainte ?", "A PIN locks NUTCADE and keeps your phrase, ecash and notes encrypted on this device. It stops someone who picks up your phone. It cannot stop malware on a device that is already compromised. If you forget it, reset the wallet and restore with your 12 words.": "Un code PIN verrouille NUTCADE et garde votre phrase, votre ecash et vos notes chiffrés sur cet appareil. Il arrête quelqu'un qui prend votre téléphone. Il ne peut pas arrêter un logiciel malveillant sur un appareil déjà compromis. Si vous l'oubliez, réinitialisez le portefeuille et restaurez avec vos 12 mots.", "The duress PIN is a second PIN that opens a small, separate wallet instead of yours, for when someone makes you unlock NUTCADE. It helps against a person standing in front of you. It does not help against someone who studies your phone with the app's open code.": "Le code PIN de contrainte est un second code qui ouvre un petit portefeuille séparé à la place du vôtre, pour le cas où quelqu'un vous force à déverrouiller NUTCADE. Il aide face à une personne qui se tient devant vous. Il n'aide pas face à quelqu'un qui étudie votre téléphone avec le code ouvert de l'app.", "Face ID or fingerprint opens your real wallet only, so turn it off if you rely on the duress PIN.": "Face ID ou l'empreinte n'ouvrent que votre vrai portefeuille, désactivez-les donc si vous comptez sur le code PIN de contrainte.", "Can I use it offline?": "Puis-je l'utiliser hors ligne ?", "Open NUTCADE once while online and it keeps a copy, so it opens without a connection after that. Offline, you can send ecash for amounts made of the exact coins you hold.": "Ouvrez NUTCADE une fois en ligne et il en garde une copie, ce qui lui permet de s'ouvrir ensuite sans connexion. Hors ligne, vous pouvez envoyer de l'ecash pour des montants formés des pièces exactes que vous détenez.", "Hide my amounts": "Masquer mes montants", "Tap your balance, or the eye button beside it, to show ••• instead of amounts on the wallet, notes and mints screens. It is remembered on this device.": "Touchez votre solde, ou le bouton en forme d'œil à côté, pour afficher ••• à la place des montants sur les écrans Portefeuille, Notes et Mints. C'est mémorisé sur cet appareil.", "Payment screens always show the real amount, so you know what you are about to send.": "Les écrans de paiement montrent toujours le vrai montant, pour que vous sachiez ce que vous allez envoyer.", "How do updates work?": "Comment fonctionnent les mises à jour ?", "NUTCADE updates itself: the next time you open it, it loads the new version, and a note tells you what changed.": "NUTCADE se met à jour tout seul : à la prochaine ouverture, il charge la nouvelle version, et une note vous dit ce qui a changé.", "If you keep it open for days, a message says when a new version is ready. Reload when you are done: NUTCADE never reloads by itself, and never offers it in the middle of a payment.": "Si vous le laissez ouvert pendant des jours, un message indique quand une nouvelle version est prête. Rechargez quand vous avez fini : NUTCADE ne se recharge jamais tout seul et ne le propose jamais en plein paiement.", "Keeping your wallet safe": "Garder votre portefeuille en sécurité", "The only real address is https://random21m.github.io/nutcade/. Anything else that calls itself NUTCADE is not us.": "La seule vraie adresse est https://random21m.github.io/nutcade/. Tout autre site qui se fait appeler NUTCADE n'est pas nous.", "On iPhone, add NUTCADE to your Home Screen. Safari can clear the storage of websites you have not opened in a while, but a Home Screen app keeps it.": "Sur iPhone, ajoutez NUTCADE à votre écran d'accueil. Safari peut effacer le stockage des sites que vous n'avez pas ouverts depuis un moment, alors qu'une app de l'écran d'accueil le garde.", "Set a PIN, keep your 12 words offline, and start with small amounts: NUTCADE is young software that has not been independently audited.": "Définissez un code PIN, gardez vos 12 mots hors ligne et commencez avec de petits montants : NUTCADE est un jeune logiciel qui n'a pas fait l'objet d'un audit indépendant.", "What does NUTCADE contact? (Privacy)": "Qui NUTCADE contacte-t-il ? (Confidentialité)", "NUTCADE has no account, no tracking, no analytics and no ads. It contacts these services, and only for the reason given:": "NUTCADE n'a ni compte, ni suivi, ni statistiques, ni publicité. Il contacte ces services, et uniquement pour la raison indiquée :", "Your mints: for every payment, to check that they answer, and to read their name and contact details. A mint sees the coins you exchange with it.": "Vos mints : pour chaque paiement, pour vérifier qu'ils répondent et pour lire leur nom et leurs coordonnées. Un mint voit les pièces que vous échangez avec lui.", "The mints in the Add mint list (Minibits, Cuba Bitcoin, 8333.space and two test mints), only while that list is open, to show whether they answer.": "Les mints de la liste Ajouter un mint (Minibits, Cuba Bitcoin, 8333.space et deux mints de test), seulement tant que cette liste est ouverte, pour montrer s'ils répondent.", "Nostr relays (relay.damus.io, nos.lol and relay.primal.net): for game challenges and payments between contacts, apps you connect with Wallet Connect, your encrypted mint list, requests you made and ecash sent to your ecash address. A contact or a payment request can name relays of its own, which are used when you send to them.": "Relais Nostr (relay.damus.io, nos.lol et relay.primal.net) : pour les défis de jeu et les paiements entre contacts, les apps que vous connectez avec Wallet Connect, votre liste de mints chiffrée, les demandes que vous avez faites et l'ecash envoyé à votre adresse ecash. Un contact ou une demande de paiement peut indiquer ses propres relais, utilisés quand vous leur envoyez quelque chose.", "Two more relays (relay.nostr.band and relay.cashumints.space) are asked only when you tap Find mints people recommend.": "Deux autres relais (relay.nostr.band et relay.cashumints.space) ne sont interrogés que lorsque vous touchez Trouver des mints recommandés.", "Coinbase, for the price and the price chart, only while Show Bitcoin price is on.": "Coinbase, pour le prix et le graphique des prix, seulement tant que Afficher le prix du Bitcoin est activé.", "npub.cash, while your Lightning address is on, and npubx.cash, when you tip from inside the app (the tip address is an npubx.cash address).": "npub.cash, tant que votre adresse Lightning est activée et npubx.cash, quand vous laissez un pourboire depuis l'app (l'adresse de pourboire est une adresse npubx.cash).", "The web address of any Lightning address, LNURL, voucher or payment request you pay or scan, and of a Nostr profile when you zap it. It sees that one request.": "L'adresse web de toute adresse Lightning, LNURL, bon ou demande de paiement que vous payez ou scannez, et celle d'un profil Nostr quand vous lui envoyez un zap. Elle voit cette seule requête.", "This website, to load NUTCADE, its QR scanner and the update check. GitHub, which hosts it, sees these requests like any website visit.": "Ce site web, pour charger NUTCADE, son lecteur de QR code et la vérification des mises à jour. GitHub, qui l'héberge, voit ces requêtes comme pour n'importe quelle visite de site.", "GitHub pages (the source, release notes and the problem report form), only when you tap a link to them.": "Pages GitHub (le code source, les notes de version et le formulaire de signalement), seulement quand vous touchez un lien vers elles.", "The camera is used only while a scanner is open and the microphone only while a Listen screen is open. Nothing is recorded or sent.": "La caméra n'est utilisée que lorsqu'un lecteur est ouvert, et le micro que lorsqu'un écran Écouter est ouvert. Rien n'est enregistré ni envoyé.", "Reporting a problem": "Signaler un problème", "Reports on GitHub are public. Never paste your 12 words, your PIN, a backup file or a token into one.": "Les signalements sur GitHub sont publics. N'y collez jamais vos 12 mots, votre code PIN, un fichier de sauvegarde ou un token.", "For a security problem, use the private report link below, so that only the maintainer sees it.": "Pour un problème de sécurité, utilisez le lien de signalement privé ci-dessous, afin que seul le mainteneur le voie.", "Your initials": "Vos initiales", "Shown on your high scores and on the challenges you play. Scores you already sent to friends keep the initials they were sent with.": "Affichées sur vos meilleurs scores et sur les défis que vous jouez. Les scores déjà envoyés à des amis gardent les initiales avec lesquelles ils ont été envoyés.", "New initials (3 letters or numbers)": "Nouvelles initiales (3 lettres ou chiffres)", "Also rename my past scores on this phone": "Renommer aussi mes anciens scores sur ce téléphone", "Save initials": "Enregistrer les initiales", "Use exactly 3 letters or numbers.": "Utilisez exactement 3 lettres ou chiffres.", "Initials saved.": "Initiales enregistrées.", "Arcade": "Arcade", "Details": "Détails", "Mint details": "Détails du mint", "ASKING THE MINT": "QUESTION AU MINT", "The mint did not answer, so there is nothing to show yet.": "Le mint n'a pas répondu, il n'y a donc encore rien à afficher.", "About this mint": "À propos de ce mint", "In more detail": "Plus en détail", "Message from the mint": "Message du mint", "Contact": "Contact", "The mint lists no contact.": "Le mint n'indique aucun contact.", "Terms of service": "Conditions d'utilisation", "The mint lists no terms.": "Le mint n'indique aucune condition.", "Software": "Logiciel", "This text was written by the mint, not by NUTCADE. Read it with care: a mint that says it is safe has not been checked by us.": "Ce texte a été écrit par le mint, pas par NUTCADE. Lisez-le avec prudence : un mint qui se dit sûr n'a pas été vérifié par nous.", "Extra protection: the app now refuses to run any code that is not its own, even if a bad mint or website tried to slip some in.": "Protection supplémentaire : l'app refuse désormais d'exécuter tout code qui n'est pas le sien, même si un mauvais mint ou site web essaie d'en glisser un.", "The backup file can be protected with a password, and it now also saves contacts, settings, trophies and arcade progress.": "Le fichier de sauvegarde peut être protégé par un mot de passe, et il contient maintenant aussi les contacts, les réglages, les trophées et la progression dans l'arcade.", "New, optional: Back up with my phone locks your 12 words with a passkey and keeps the locked copy on Nostr relays.": "Nouveau, en option : Sauvegarder avec mon téléphone verrouille vos 12 mots avec une clé d'accès et garde la copie verrouillée sur des relais Nostr.", "It also holds your contacts, settings, trophies and arcade progress.": "Il contient aussi vos contacts, vos réglages, vos trophées et votre progression dans l'arcade.", "Protect with a password": "Protéger par un mot de passe", "The file can only be opened with the password you choose.": "Le fichier ne peut être ouvert qu'avec le mot de passe que vous choisissez.", "Choose a password for the file. Anyone with the file and the password can spend your sats.": "Choisissez un mot de passe pour le fichier. Quiconque a le fichier et le mot de passe peut dépenser vos sats.", "Password": "Mot de passe", "Same password again": "Le même mot de passe à nouveau", "NUTCADE can't recover a forgotten password. Your 12 words still restore your sats.": "NUTCADE ne peut pas retrouver un mot de passe oublié. Vos 12 mots restaurent toujours vos sats.", "Download locked backup": "Télécharger la sauvegarde verrouillée", "Locked backup file downloaded. Keep the password safe.": "Fichier de sauvegarde verrouillé téléchargé. Gardez le mot de passe en lieu sûr.", "Use at least 8 characters for the password.": "Utilisez au moins 8 caractères pour le mot de passe.", "The two passwords don't match.": "Les deux mots de passe ne correspondent pas.", "Backup password": "Mot de passe de la sauvegarde", "This backup is locked with a password.": "Cette sauvegarde est verrouillée par un mot de passe.", "Type the backup's password.": "Saisissez le mot de passe de la sauvegarde.", "Wrong password, or the file is damaged. Nothing was changed.": "Mot de passe incorrect, ou le fichier est endommagé. Rien n'a été modifié.", "This locked backup was made by a newer NUTCADE or is damaged. Nothing was changed.": "Cette sauvegarde verrouillée a été faite par un NUTCADE plus récent ou est endommagée. Rien n'a été modifié.", "Back up with my phone": "Sauvegarder avec mon téléphone", "Restore with my phone": "Restaurer avec mon téléphone", "Locks your 12 words with a passkey (Face ID or fingerprint) and keeps the locked copy on Nostr relays. A new phone gets them back with the same passkey. Your 12 words stay your main backup.": "Verrouille vos 12 mots avec une clé d'accès (Face ID ou empreinte) et garde la copie verrouillée sur des relais Nostr. Un nouveau téléphone les récupère avec la même clé d'accès. Vos 12 mots restent votre sauvegarde principale.", "Phone backup": "Sauvegarde téléphone", "NOT SET UP": "NON CONFIGURÉE", "OUT OF DATE": "PÉRIMÉE", "It holds your old 12 words. Tap Back up again to save the new ones.": "Elle contient vos anciens 12 mots. Touchez Sauvegarder à nouveau pour enregistrer les nouveaux.", "Back up again": "Sauvegarder à nouveau", "Remove phone backup": "Supprimer la sauvegarde téléphone", "Your Apple or Google account becomes a key to your wallet: anyone who gets into it can use the passkey to get your 12 words back. Keep that account safe, with two-step sign-in.": "Votre compte Apple ou Google devient une clé de votre portefeuille : quiconque y accède peut utiliser la clé d'accès pour récupérer vos 12 mots. Protégez ce compte avec la validation en deux étapes.", "NUTCADE makes a passkey on this phone (kept in iCloud Keychain or Google Password Manager), locks your 12 words with it and saves the locked copy on Nostr relays. No server of ours is involved.": "NUTCADE crée une clé d'accès sur ce téléphone (gardée dans le trousseau iCloud ou le gestionnaire de mots de passe de Google), verrouille vos 12 mots avec elle et garde la copie verrouillée sur des relais Nostr. Aucun serveur à nous n'intervient.", "Keep your 12 words on paper too. They are still your main backup.": "Gardez aussi vos 12 mots sur papier. Ils restent votre sauvegarde principale.", "BACKED UP!": "SAUVEGARDÉ !", "Your 12 words are locked with your passkey and saved on {#} relay. On a new phone, tap Restore with my phone.": "Vos 12 mots sont verrouillés avec votre clé d'accès et enregistrés sur {#} relais. Sur un nouveau téléphone, touchez Restaurer avec mon téléphone.", "Your 12 words are locked with your passkey and saved on {#} relays. On a new phone, tap Restore with my phone.": "Vos 12 mots sont verrouillés avec votre clé d'accès et enregistrés sur {#} relais. Sur un nouveau téléphone, touchez Restaurer avec mon téléphone.", "NUTCADE asks the Nostr relays to delete the locked copy of your 12 words. A relay that is down or ignores the request can keep it, still locked with your passkey.": "NUTCADE demande aux relais Nostr de supprimer la copie verrouillée de vos 12 mots. Un relais en panne ou qui ignore la demande peut la garder, toujours verrouillée par votre clé d'accès.", "You can also delete the passkey in your password manager.": "Vous pouvez aussi supprimer la clé d'accès dans votre gestionnaire de mots de passe.", "REMOVING": "SUPPRESSION", "RESETTING": "RÉINITIALISATION", "Phone backup removed.": "Sauvegarde téléphone supprimée.", "Your 12 words came from your phone backup. They are not shown here.": "Vos 12 mots viennent de votre sauvegarde téléphone. Ils ne sont pas affichés ici.", "Enter your PIN to back up your 12 words with your phone.": "Saisissez votre code PIN pour sauvegarder vos 12 mots avec votre téléphone.", "Back up with my phone isn't available right now. Try again later.": "Sauvegarder avec mon téléphone n'est pas disponible pour l'instant. Réessayez plus tard.", "Restore with my phone isn't available right now. Try again later.": "Restaurer avec mon téléphone n'est pas disponible pour l'instant. Réessayez plus tard.", "This phone or browser can't lock your words with a passkey. Nothing was saved. Your 12 words are still your backup.": "Ce téléphone ou ce navigateur ne peut pas verrouiller vos mots avec une clé d'accès. Rien n'a été enregistré. Vos 12 mots restent votre sauvegarde.", "Create or restore a wallet first.": "Créez ou restaurez d'abord un portefeuille.", "Back up with my phone needs a connection. Try again online.": "Sauvegarder avec mon téléphone a besoin d'une connexion. Réessayez une fois en ligne.", "Restore with my phone needs a connection. Try again online.": "Restaurer avec mon téléphone a besoin d'une connexion. Réessayez une fois en ligne.", "No Nostr relay answered, so nothing was saved. Check your connection and try again.": "Aucun relais Nostr n'a répondu, donc rien n'a été enregistré. Vérifiez votre connexion et réessayez.", "No Nostr relay answered, so the phone backup is still there. Try again online.": "Aucun relais Nostr n'a répondu, donc la sauvegarde téléphone est toujours là. Réessayez une fois en ligne.", "The passkey step was cancelled. Nothing was changed.": "L'étape de la clé d'accès a été annulée. Rien n'a été modifié.", "That passkey isn't a NUTCADE phone backup. Nothing was changed.": "Cette clé d'accès n'est pas une sauvegarde téléphone NUTCADE. Rien n'a été modifié.", "This phone or browser can't open a phone backup. Nothing was changed. Use your 12 words.": "Ce téléphone ou ce navigateur ne peut pas ouvrir une sauvegarde téléphone. Rien n'a été modifié. Utilisez vos 12 mots.", "No Nostr relay answered. Check your connection and try again. Nothing was changed.": "Aucun relais Nostr n'a répondu. Vérifiez votre connexion et réessayez. Rien n'a été modifié.", "No phone backup was found for this passkey. Nothing was changed.": "Aucune sauvegarde téléphone n'a été trouvée pour cette clé d'accès. Rien n'a été modifié.", "This phone backup couldn't be opened with this passkey. Nothing was changed.": "Cette sauvegarde téléphone n'a pas pu être ouverte avec cette clé d'accès. Rien n'a été modifié.", "This also deletes your phone backup from the Nostr relays, so Restore with my phone will not bring this wallet back. Without your 12 words, your sats are gone for good.": "Cela supprime aussi votre sauvegarde téléphone des relais Nostr, donc Restaurer avec mon téléphone ne ramènera pas ce portefeuille. Sans vos 12 mots, vos sats sont perdus pour de bon.", "Your phone backup holds this wallet's 12 words. If this changes them, the phone backup is out of date until you tap Back up again in Settings.": "Votre sauvegarde téléphone contient les 12 mots de ce portefeuille. Si cette étape les change, la sauvegarde téléphone est périmée jusqu'à ce que vous touchiez Sauvegarder à nouveau dans les Réglages.", "After this, Restore with my phone will not bring this wallet back. Keep your 12 words.": "Après cela, Restaurer avec mon téléphone ne ramènera pas ce portefeuille. Gardez vos 12 mots.", "A phone backup, if you made one, is not deleted by this reset: it stays on the Nostr relays, and Restore with my phone can bring the wallet back.": "Une sauvegarde téléphone, si vous en avez fait une, n'est pas supprimée par cette réinitialisation : elle reste sur les relais Nostr, et Restaurer avec mon téléphone peut ramener le portefeuille.", "The copy on the Nostr relays for this passkey holds other 12 words, saved from another phone or another wallet. Replacing it means that phone backup is lost.": "La copie sur les relais Nostr pour cette clé d'accès contient d'autres 12 mots, enregistrés depuis un autre téléphone ou un autre portefeuille. La remplacer, c'est perdre cette sauvegarde téléphone.", "Replace anyway": "Remplacer quand même", "Your phone backup's passkey wasn't found, or the step was cancelled. If you deleted the passkey, tap Remove phone backup, then back up again.": "La clé d'accès de votre sauvegarde téléphone est introuvable, ou l'étape a été annulée. Si vous avez supprimé la clé d'accès, touchez Supprimer la sauvegarde téléphone, puis sauvegardez à nouveau.", "Contacts: {#} added, {#} skipped (the same name or address is already here, or it wasn't valid).": "Contacts : {#} ajoutés, {#} ignorés (le même nom ou la même adresse existe déjà, ou il n'était pas valide)."});
})();
